/*! bridgey site views (build 時に views/*.html から生成) */
window.__BRIDGEY_VIEWS = {"home":"<a id=\"top\"></a>\n\n<style>\n  /* この画面のデモ用。ライブラリの機能ではなく、ページの装飾。 */\n  .demo-row { display: flex; align-items: center; justify-content: space-between; padding: 10px 0; }\n  .demo-row + .demo-row { border-top: 1px dashed var(--line, #e3e6ea); }\n  .demo-qty { display: inline-flex; align-items: center; gap: 14px; }\n  .demo-qty button { width: 38px; height: 38px; border-radius: 50%; font-size: 17px; cursor: pointer; border: 1px solid var(--line, #e3e6ea); background: transparent; color: inherit; }\n  .demo-qty b { min-width: 2.2em; text-align: center; font-size: 20px; font-variant-numeric: tabular-nums; }\n  .demo-price { font-size: 26px; font-weight: 700; letter-spacing: -.02em; }\n  .demo-price small { font-size: 12px; font-weight: 400; opacity: .7; margin-left: 2px; }\n  .demo-free { color: #1a7f37; font-size: 13px; margin: 8px 0 0; }\n  [data-theme=\"dark\"] .demo-free { color: #3fb950; }\n  .demo-bar { height: 8px; border-radius: 99px; background: var(--line, #e3e6ea); overflow: hidden; margin-top: 12px; }\n  .demo-bar > i { display: block; height: 100%; width: var(--progress, 0%); background: linear-gradient(90deg, #6d5efc, #22c1a6); transition: width .3s; }\n  .accident { list-style: none; padding: 0; margin: 0; }\n  .accident li { padding: 12px 0; border-top: 1px solid var(--line, #e3e6ea); font-size: 14.5px; }\n  .accident li:first-child { border-top: none; }\n  .accident b { display: block; margin-bottom: 2px; }\n  .compare { width: 100%; border-collapse: collapse; font-size: 13.5px; }\n  .compare th, .compare td { text-align: left; padding: 9px 12px; border-bottom: 1px solid var(--line, #e3e6ea); }\n  .compare th { font-weight: 600; opacity: .7; font-size: 12.5px; }\n  .compare code { font-size: 12.5px; }\n  .compare tr td:first-child { white-space: nowrap; }\n</style>\n\n<div class=\"wrap\">\n  <section class=\"hero\" style=\"border-top:none\">\n    <img class=\"mark\" src=\"./logo.svg\" alt=\"bridgey\" />\n    <h1>jQuery のまま、<br /><span class=\"grad-text\">モダンに。</span></h1>\n    <p class=\"lead\">\n      <strong>レガシーな現場を少しモダンにするライブラリです。</strong><br />\n      導入は<code>&lt;script&gt;</code> 1行。<b>HTMLは1文字も変えなくていい</b>し、<br>いま動いているjQueryも1行も変えなくていい。\n    </p>\n    <div class=\"cta\">\n      <a class=\"btn primary\" href=\"#/tutorial\"><i class=\"fa-solid fa-graduation-cap\"></i> チュートリアルを始める</a>\n      <a class=\"btn ghost\" href=\"#/examples\"><i class=\"fa-regular fa-circle-play\"></i> デモを見る</a>\n    </div>\n    <div class=\"install cdn\">\n      <span class=\"dollar\">CDN</span><span class=\"url\">https://cdn.jsdelivr.net/npm/bridgey@2</span>\n      <button class=\"copy\" data-copy=\"&lt;script src=&quot;https://cdn.jsdelivr.net/npm/bridgey@2&quot;&gt;&lt;/script&gt;\"><i class=\"fa-regular fa-copy\"></i> copy</button>\n    </div>\n    <div class=\"install\">\n      <span class=\"dollar\">$</span><span>npm install bridgey</span>\n      <button class=\"copy\" data-copy=\"npm install bridgey\"><i class=\"fa-regular fa-copy\"></i> copy</button>\n    </div>\n  </section>\n</div>\n\n<!-- ライブデモ -->\n<section id=\"live\" class=\"anchor\">\n  <div class=\"wrap\">\n    <div class=\"eyebrow\">動いています</div>\n    <h2>状態が変わると、画面が追いつく。</h2>\n    <p class=\"sub\">下のカードは <b>このページの中で実際に動いています</b>。増えた概念は1つだけです。</p>\n\n    <!-- sample:home-demo:start -->\n<div class=\"card\" data-component=\"home-demo\">\n        <div class=\"demo-row\">\n          <span>数量</span>\n          <span class=\"demo-qty\">\n            <button data-brg=\"dec\" aria-label=\"減らす\">−</button>\n            <b data-brg=\"qty\"></b>\n            <button data-brg=\"inc\" aria-label=\"増やす\">＋</button>\n          </span>\n        </div>\n        <div class=\"demo-row\">\n          <span>合計</span>\n          <span class=\"demo-price\"><span data-brg=\"total\"></span><small>円</small></span>\n        </div>\n        <p class=\"demo-free\" data-brg=\"free\">3個以上で送料無料になりました</p>\n        <div class=\"demo-bar\" data-brg=\"bar\"><i></i></div>\n      </div>\n<!-- sample:home-demo:end -->\n\n      <div class=\"card\">\n        <div class=\"label\"><i class=\"fa-solid fa-code\"></i> いま動いているコード</div>\n        <div data-brg=\"home-demo-source\"></div>\n        <template data-brg=\"home-demo-source-jquery\"><pre><code>// ※ 同じ画面を jQuery で書いた場合。掴む先には id / class を振った前提です。\nvar UNIT_PRICE = 1100;\nvar quantity   = 1;\n\n// 表示を更新する関数を1つ作り、変えた場所すべてから呼ぶ\nfunction render() {\n  $(\"#qty\").text(quantity);\n  $(\"#total\").text((quantity * UNIT_PRICE).toLocaleString());  // 書き忘れると数値計算が合わない\n  $(\"#free\").toggle(quantity >= 3);\n  $(\"#bar > i\").css(\"width\", Math.min(100, quantity * 20) + \"%\");\n}\n\n$(\"#inc\").on(\"click\", function () {\n  quantity = quantity + 1;\n  render();          // ← 呼び忘れたら画面が止まる\n});\n\n$(\"#dec\").on(\"click\", function () {\n  quantity = Math.max(1, quantity - 1);\n  render();          // ← 呼び忘れたら画面が止まる\n});\n\nrender();            // 初期表示のためにもう1回</code></pre></template>\n        <p style=\"color:var(--muted);font-size:13px;margin-top:10px\">\n          <code>total</code> に<b>代入している行はどこにもありません</b>。導出しているだけです。<br />\n          だから「更新を忘れて数値計算が合わない」が起きません。\n        </p>\n    </div>\n\n    <p style=\"color:var(--muted);font-size:13px;margin-top:14px\">\n      ※ HTML に出てくる <code>data-brg</code> は<b>推奨であって、必須ではありません</b>。\n      <code>$$(\"#total\")</code> <code>$$(\".total\")</code> のように<b>いま付いている id や class のまま書けます</b>\n      （HTML を触れない現場のため）。触れるなら <code>data-brg</code> に分けておくと、\n      デザイナーが class を変えても JS が壊れなくなります。<br />\n      ※ このサイト自身も bridgey で動いています（ルーティング・テーマ・このデモ全部）。\n      SPA で差し込まれた HTML にも <code>data-component</code> だけで自動適用されます。\n    </p>\n  </div>\n</section>\n\n<!-- WHY -->\n<section id=\"why\" class=\"anchor\">\n  <div class=\"wrap\">\n    <div class=\"eyebrow\">なぜ bridgey か</div>\n    <h2>jQuery でよく起きる事故を、止めます。</h2>\n    <p class=\"sub\">どれも保守の現場で繰り返し起きている問題への対策です。</p>\n\n    <div class=\"grid\">\n      <div class=\"card\">\n        <div class=\"ico\"><i class=\"fa-solid fa-calculator\"></i></div>\n        <h3>数値計算が合わない</h3>\n        <p><code>change</code> の中で合計を計算して代入していた。初期表示で走らない／別の箇所で上書き／動的に足した項目に効かない。<br />\n          <b>→ 合計は導出値。代入する場所が存在しないので、更新漏れが起きません。</b></p>\n      </div>\n      <div class=\"card\">\n        <div class=\"ico\"><i class=\"fa-solid fa-eye-slash\"></i></div>\n        <h3>非表示の必須項目で送信できない</h3>\n        <p>画面に出ていない <code>required</code> で送信がブロックされ、理由も表示されない。ユーザーは離脱し、CVが消える。<br />\n          <b>→ 見えているフィールドだけを検証します。</b></p>\n      </div>\n      <div class=\"card\">\n        <div class=\"ico\"><i class=\"fa-solid fa-keyboard\"></i></div>\n        <h3>オートフィルで入力しても未入力扱い</h3>\n        <p>自動入力や JS 代入では <code>input</code> が飛ばないので、検証が走らない。埋まっているのに送信できない。<br />\n          <b>→ 値の代入自体を検知します（既存 jQuery の <code>.val()</code> 経由でも）。</b></p>\n      </div>\n      <div class=\"card\">\n        <div class=\"ico\"><i class=\"fa-solid fa-link-slash\"></i></div>\n        <h3>HTMLを1つ挟むと静かに壊れる</h3>\n        <p><code>next()</code> <code>children()</code> <code>eq()</code> は構造に依存する。要素を1つラップしただけで、例外も出ないまま動かなくなる。<br />\n          <b>→ 名前で引きます。0件なら警告します（jQueryは黙ります）。</b></p>\n      </div>\n      <div class=\"card\">\n        <div class=\"ico\"><i class=\"fa-solid fa-skull\"></i></div>\n        <h3>1つの undefined で全機能が死ぬ</h3>\n        <p><code>common.js</code> の <code>$(function(){})</code> の中で1箇所 undefined を踏むと、以降に登録されるタブ・モーダル・アコーディオンが全部死ぬ。<br />\n          <b>→ 部品単位でエラーを隔離します。壊れたものだけが止まります。</b></p>\n      </div>\n      <div class=\"card\">\n        <div class=\"ico\"><i class=\"fa-solid fa-language\"></i></div>\n        <h3>日本語入力で壊れる</h3>\n        <p>変換中に値を書き戻すと、変換候補が消える・確定できない・文字が化ける。電話番号や全角半角の自動整形で必ず起きる。<br />\n          <b>→ 変換中は値を触りません。海外製ライブラリはここを見ていません。</b></p>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- MIGRATION -->\n<section id=\"philosophy\" class=\"anchor\">\n  <div class=\"wrap\">\n    <div class=\"eyebrow\">段階的移行</div>\n    <h2>全部書き直さなくていい。1機能から。</h2>\n    <p class=\"sub\">\n      レガシーな技術を止められない現場のために。これが最優先の設計です。<br />\n    </p>\n\n    <div class=\"steps ladder\">\n      <div class=\"step\">\n        <div class=\"n\"></div>\n        <div>\n          <b>いまのやり方（そのまま動く）</b>\n          <pre><code>$(<span class=\"tok-s\">\".tab\"</span>).on(<span class=\"tok-s\">\"click\"</span>, <span class=\"tok-k\">function</span> () {\n  $(<span class=\"tok-s\">\".tab\"</span>).removeClass(<span class=\"tok-s\">\"active\"</span>);\n  $(<span class=\"tok-k\">this</span>).addClass(<span class=\"tok-s\">\"active\"</span>);\n});</code></pre>\n        </div>\n      </div>\n      <div class=\"step\">\n        <div class=\"n\"></div>\n        <div>\n          <b>bridgey の JS API — 事故が減る</b>\n          <pre><code><span class=\"tok-k\">const</span> current = $$.<span class=\"tok-f\">state</span>(<span class=\"tok-s\">\"a\"</span>);\n$$(<span class=\"tok-s\">\".tab\"</span>).each((el) =&gt; $$(el)\n  .click(() =&gt; current(el.dataset.tab))\n  .selected(() =&gt; current() === el.dataset.tab));</code></pre>\n        </div>\n      </div>\n      <div class=\"step\">\n        <div class=\"n\"></div>\n        <div>\n          <b>そのまま、事故の起きない形に寄せていく</b>\n          <pre><code><span class=\"tok-c\">// 合計は「代入」ではなく「導出」にする → 更新漏れが消える</span>\n<span class=\"tok-k\">const</span> total = $$.<span class=\"tok-f\">computed</span>(() =&gt; picked().reduce((s, k) =&gt; s + PRICE[k], 0));\n$$(<span class=\"tok-s\">\"#total\"</span>).text(total, $$.money, <span class=\"tok-s\">\"円\"</span>);\n\n<span class=\"tok-c\">// 一覧は repeat に任せる → 入力途中もフォーカスも飛ばない</span>\n$$(<span class=\"tok-s\">\"#list\"</span>).repeat(items, { key: (i) =&gt; i.id, tpl: <span class=\"tok-s\">\"#row\"</span>, render: … });\n\n<span class=\"tok-c\">// common.js は「登録」だけにする → 1つ壊れても他は動く</span>\n$$.<span class=\"tok-f\">component</span>(<span class=\"tok-s\">\"tabs\"</span>, ($el) =&gt; { … });</code></pre>\n        </div>\n      </div>\n    </div>\n\n    <p style=\"color:var(--muted);font-size:13.5px;margin-top:18px\">\n      ①で止めてもいい。②で止めてもいい。<b>止めたところまでの分だけ、事故が減っています。</b><br />\n      新しいフレームワークを入れる稟議も、ビルド環境の用意も、要りません。\n    </p>\n  </div>\n</section>\n\n<!-- START -->\n<section id=\"start\" class=\"anchor\">\n  <div class=\"wrap\">\n    <div class=\"eyebrow\">インストール</div>\n    <h2>&lt;script&gt; 1行から。</h2>\n    <p class=\"sub\">今すぐ試すなら CDN。型が欲しくなったら npm。どちらでも機能は同じです。</p>\n\n    <div class=\"two\">\n      <div class=\"card\">\n        <div class=\"label\"><i class=\"fa-solid fa-bolt\"></i> &lt;script&gt; 1行（ビルド不要）</div>\n        <pre><code>&lt;p&gt;合計 &lt;span id=<span class=\"tok-s\">\"total\"</span>&gt;0&lt;/span&gt; 円&lt;/p&gt;\n&lt;button id=<span class=\"tok-s\">\"add\"</span>&gt;追加する&lt;/button&gt;\n\n&lt;script src=<span class=\"tok-s\">\"https://cdn.jsdelivr.net/npm/bridgey@2\"</span>&gt;&lt;/script&gt;\n&lt;script&gt;\n  <span class=\"tok-k\">const</span> count = $$.<span class=\"tok-f\">state</span>(0);\n  <span class=\"tok-k\">const</span> total = $$.<span class=\"tok-f\">computed</span>(() =&gt; count() * 1100);\n\n  $$(<span class=\"tok-s\">\"#total\"</span>).text(total, $$.money);\n  $$(<span class=\"tok-s\">\"#add\"</span>).click(() =&gt; count(n =&gt; n + 1));\n&lt;/script&gt;</code></pre>\n        <p style=\"color:var(--muted);font-size:13.5px;margin-top:12px\">\n          <code>$</code> を <code>$$</code> にするだけ。<b>増えた概念は1つだけ</b>です:\n          値を渡すと1回きり、<code>state</code> を渡すとずっと追いかける。\n        </p>\n      </div>\n      <div class=\"card\">\n        <div class=\"label\"><i class=\"fa-brands fa-npm\"></i> npm（型が付きます）</div>\n        <pre><code>npm install bridgey</code></pre>\n        <pre><code><span class=\"tok-k\">import</span> { $$ } <span class=\"tok-k\">from</span> <span class=\"tok-s\">\"bridgey\"</span>;\n<span class=\"tok-k\">import</span> { $$ <span class=\"tok-k\">as</span> $ } <span class=\"tok-k\">from</span> <span class=\"tok-s\">\"bridgey\"</span>;  <span class=\"tok-c\">// 好きな名前に</span></code></pre>\n        <p style=\"color:var(--muted);font-size:13.5px;margin:12px 0 0\">\n          TypeScript で書かれているので、型定義が実装とズレません。<br />\n          <code>&lt;script&gt;</code> で読むときは、<b>名前を1箇所で変えられます。</b>\n        </p>\n        <pre><code>&lt;script src=<span class=\"tok-s\">\"…/bridgey@2\"</span>&gt;&lt;/script&gt;                       <span class=\"tok-c\">// $$（既定）</span>\n&lt;script src=<span class=\"tok-s\">\"…/bridgey@2\"</span> data-global=<span class=\"tok-s\">\"$\"</span>&gt;&lt;/script&gt;      <span class=\"tok-c\">// $ で呼べる</span>\n&lt;script src=<span class=\"tok-s\">\"…/bridgey@2\"</span> data-global=<span class=\"tok-s\">\"brg\"</span>&gt;&lt;/script&gt;    <span class=\"tok-c\">// brg で呼べる</span>\n&lt;script src=<span class=\"tok-s\">\"…/bridgey@2\"</span> data-global=<span class=\"tok-s\">\"brg,$$\"</span>&gt;&lt;/script&gt; <span class=\"tok-c\">// 両方の名前で呼べる</span></code></pre>\n      </div>\n    </div>\n\n  </div>\n</section>\n\n<!-- WORDS -->\n<section id=\"words\" class=\"anchor\">\n  <div class=\"wrap\">\n    <div class=\"eyebrow\">覚えること</div>\n    <h2>まず4語。</h2>\n    <p class=\"sub\">残りは知らなくても詰まりません。必要になった場面で bridgey が教えます。</p>\n\n    <div class=\"card\">\n      <ul class=\"accident\">\n        <li><b><code>state</code> / <code>computed</code> / <code>when</code> / <code>repeat</code></b>\n          状態を作る・計算する・出し入れする・一覧を描く。<b>これで8割書けます。</b></li>\n        <li><b>困ったら: <code>form</code> / <code>group</code> / <code>component</code> / <code>resource</code></b>\n          フォームの事故・選択の管理・common.js の安全化・通信の競合。</li>\n        <li><b>残りは出会ったときに</b>\n          <code>mode</code> <code>vars</code> <code>selected</code> <code>expanded</code> <code>invalid</code> <code>busy</code>\n          <code>disabled</code> <code>action</code> <code>scope</code> <code>effect</code> <code>money</code> …<br />\n          <code>.addClass(\"active\")</code> と書いた瞬間に「<code>.selected(state)</code> が使えます」と教えます。</li>\n      </ul>\n    </div>\n\n    <p style=\"margin-top:24px\">\n      <a class=\"btn primary\" href=\"#/tutorial\"><i class=\"fa-solid fa-graduation-cap\"></i> チュートリアルで手を動かす</a>\n      <a class=\"btn ghost\" href=\"#/examples\"><i class=\"fa-regular fa-circle-play\"></i> 複雑なフォームの比較を見る</a>\n      <a class=\"btn ghost\" href=\"#/docs\"><i class=\"fa-solid fa-book\"></i> ドキュメント</a>\n    </p>\n  </div>\n</section>\n\n<!-- NOT INCLUDED -->\n<section id=\"scope\" class=\"anchor\">\n  <div class=\"wrap\">\n    <div class=\"eyebrow\">jQuery 互換</div>\n    <h2>保守の手を止めず、<br />より安全な書き方へ。</h2>\n    <p class=\"sub\">\n      <b>既存コードをコピペしても1行目で落ちません。</b>後方互換を保ちつつ、モダンな機能を段階導入していきます。<br />\n      そのうえで事故になりやすい書き方には、<b>開発時に1回だけヒント</b>が出ます（<code>$$.hints = false</code> で止まります）。\n    </p>\n    <div class=\"card\" style=\"overflow-x:auto\">\n      <table class=\"compare\">\n        <thead><tr><th>そのまま動くもの</th><th>ヒントで案内する、より安全な書き方</th></tr></thead>\n        <tbody>\n          <tr><td><code>next</code> / <code>prev</code> / <code>siblings</code> / <code>eq</code> / <code>index</code></td><td><code>closest(\"@row\").find(\"@price\")</code>（構造ではなく名前で引く）</td></tr>\n          <tr><td><code>show</code> / <code>hide</code> / <code>toggle</code></td><td><code>when(state)</code>（表示を状態から導出する）</td></tr>\n          <tr><td><code>fadeIn</code> / <code>fadeOut</code> / <code>slideToggle</code></td><td>CSS の <code>transition</code> ＋ <code>.toggleClass(\"is-open\", state)</code></td></tr>\n          <tr><td><code>$$.ajax</code> / <code>$$.get</code> / <code>$$.post</code></td><td><code>$$.resource()</code>（後着追い越しを防ぐ）／<code>$$.action()</code>（二重送信を防ぐ）</td></tr>\n          <tr><td><code>$$.each</code> / <code>$$.map</code> / <code>$$.extend</code> / <code>$$.trim</code></td><td>ヒントなし（危険ではないので、そのまま使ってください）</td></tr>\n          <tr><td><code>serialize</code> / <code>serializeArray</code></td><td>ヒントなし（検証は <code>form()</code> が担当します）</td></tr>\n          <tr><td><code>prepend</code> / <code>before</code> / <code>after</code> / <code>clone</code> / <code>wrap</code> / <code>detach</code></td><td>ヒントなし（一覧は <code>repeat()</code> の方が安全です）</td></tr>\n          <tr><td><code>width</code> / <code>height</code> / <code>offset</code> / <code>position</code> / <code>scrollTop</code></td><td>ヒントなし</td></tr>\n          <tr><td><code>one</code> / <code>trigger</code> / <code>hover</code> / <code>ready</code></td><td>ヒントなし</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <p style=\"color:var(--muted);font-size:13px;margin-top:12px\">\n      <b>入れないもの:</b> ルーター / SPA 化（URL の主権はサーバーに）・スコープ付き CSS・仮想DOM・SSR。<br />\n      jQuery プラグイン（slick / DataTables 等）は bridgey では動きません。jQuery 本体と<b>併用</b>してください（<code>$</code> は奪いません）。\n    </p>\n  </div>\n</section>\n","docs":"<a id=\"top\"></a>\n<div class=\"wrap\">\n  <div class=\"layout\">\n    <aside class=\"toc\">\n      <div class=\"grp\">はじめに</div>\n      <a href=\"#intro\">bridgey とは</a>\n      <a href=\"#install\">インストール</a>\n      <a href=\"#hello\">はじめの一歩</a>\n      <a href=\"#one\">増えた概念は1つだけ</a>\n      <a href=\"#selector\">セレクタと @ 略記</a>\n\n      <div class=\"grp\">まず4語</div>\n      <a href=\"#state\">state</a>\n      <a href=\"#computed\">computed</a>\n      <a href=\"#when\">when</a>\n      <a href=\"#repeat\">repeat</a>\n\n      <div class=\"grp\">知っている jQuery</div>\n      <a href=\"#dollar\">$$( ) が受け取れるもの</a>\n      <a href=\"#content\">text / html / val / attr / prop / css</a>\n      <a href=\"#uistate\">UI 状態（selected / disabled …）</a>\n      <a href=\"#mode\">mode / toggleAttr / vars</a>\n      <a href=\"#traverse\">走査</a>\n      <a href=\"#events\">イベント</a>\n      <a href=\"#manip\">追加・削除</a>\n\n      <div class=\"grp\">困ったら4語</div>\n      <a href=\"#form\">form（フォームの事故）</a>\n      <a href=\"#group\">group（選択）</a>\n      <a href=\"#component\">component（common.js）</a>\n      <a href=\"#resource\">resource / action（通信）</a>\n\n      <div class=\"grp\">事故を防ぐしくみ</div>\n      <a href=\"#warnings\">警告</a>\n      <a href=\"#hints\">ヒント</a>\n      <a href=\"#ime\">日本語入力</a>\n\n      <div class=\"grp\">配布と設定</div>\n      <a href=\"#dist\">&lt;script&gt; と npm</a>\n      <a href=\"#global-name\">グローバル名を変える</a>\n      <a href=\"#config\">設定と補助</a>\n\n      <div class=\"grp\">その他</div>\n      <a href=\"#removed\">持たないもの</a>\n      <a href=\"#v1\">v1 からの移行</a>\n    </aside>\n\n    <main class=\"content\">\n      <h1>ドキュメント</h1>\n      <p class=\"muted\">\n        まず覚えるのは <code>state</code> / <code>computed</code> / <code>when</code> / <code>repeat</code> の4語だけ。\n        あとは知っている jQuery のメソッドがそのまま使えます。<br />\n        依存ゼロ・ビルド不要・gzip 16kB・<code>eval</code> 不使用（CSPセーフ）。\n      </p>\n\n      <!-- ============ はじめに ============ -->\n      <h2 id=\"intro\" class=\"anchor\">bridgey とは</h2>\n      <p>\n        <b>\n          保守する人のためのライブラリです。</b>jQuery で書かれた画面を、書き直さずに事故だけ止めるための道具です。<br>\n        すべて実在のコードで起きていた事故が出発点です。\n      </p>\n      <ul>\n        <li><b>数字（金額など）の合計値が合わない</b> — 合計を「代入する場所」を無くしました</li>\n        <li><b>非表示の必須項目で送信できない</b> — 見えているフィールドだけを検証します</li>\n        <li><b>オートフィルで未入力扱い</b> — 値の代入自体を検知します</li>\n        <li><b>HTMLの構造が変わりJSが壊れる</b> — 名前で引き、0件なら警告します</li>\n        <li><b>1つの undefined で全機能が死ぬ</b> — 部品単位でエラーを隔離します</li>\n        <li><b>日本語入力で壊れる</b> — 変換中は値を触りません</li>\n      </ul>\n      <div class=\"note\">\n        <p style=\"margin:0\">\n          ビルド環境も、HTML の書き換えも、既存 jQuery の削除も、全面書き直しも要求しません。<br />\n          <code>&lt;script&gt;</code> 1行を足して、<b>1機能だけ</b>置き換えられます。\n        </p>\n      </div>\n\n      <h2 id=\"install\" class=\"anchor\">インストール</h2>\n      <p>今すぐ試すなら <code>&lt;script&gt;</code> 1行。型が欲しくなったら npm。</p>\n      <pre><code><span class=\"tok-c\">&lt;!-- これだけ。ビルド不要 --&gt;</span>\n&lt;script src=<span class=\"tok-s\">\"https://cdn.jsdelivr.net/npm/bridgey@2\"</span>&gt;&lt;/script&gt;</code></pre>\n      <pre><code>npm install bridgey</code></pre>\n      <pre><code><span class=\"tok-k\">import</span> { $$ } <span class=\"tok-k\">from</span> <span class=\"tok-s\">\"bridgey\"</span>;\n<span class=\"tok-k\">import</span> { $$ <span class=\"tok-k\">as</span> $ } <span class=\"tok-k\">from</span> <span class=\"tok-s\">\"bridgey\"</span>;   <span class=\"tok-c\">// 好きな名前にできる</span></code></pre>\n\n      <h2 id=\"hello\" class=\"anchor\">はじめの一歩</h2>\n      <p><b><code>demo.html</code> という名前で保存して、ブラウザで開くだけ</b>です。これで全部です。</p>\n      <pre><code><span class=\"tok-c\">&lt;!doctype html&gt;</span>\n&lt;html lang=<span class=\"tok-s\">\"ja\"</span>&gt;\n&lt;head&gt;\n&lt;meta charset=<span class=\"tok-s\">\"utf-8\"</span>&gt;\n&lt;title&gt;demo&lt;/title&gt;\n&lt;/head&gt;\n&lt;body&gt;\n\n&lt;p&gt;合計 &lt;span id=<span class=\"tok-s\">\"total\"</span>&gt;0&lt;/span&gt; 円&lt;/p&gt;\n&lt;button id=<span class=\"tok-s\">\"add\"</span>&gt;追加する&lt;/button&gt;\n\n&lt;script src=<span class=\"tok-s\">\"https://cdn.jsdelivr.net/npm/bridgey@2\"</span>&gt;&lt;/script&gt;\n&lt;script&gt;\n  <span class=\"tok-k\">const</span> count = $$.<span class=\"tok-f\">state</span>(0);\n  <span class=\"tok-k\">const</span> total = $$.<span class=\"tok-f\">computed</span>(() =&gt; count() * 1100);\n\n  $$(<span class=\"tok-s\">\"#total\"</span>).text(total, $$.money);\n  $$(<span class=\"tok-s\">\"#add\"</span>).click(() =&gt; count(n =&gt; n + 1));\n&lt;/script&gt;\n\n&lt;/body&gt;\n&lt;/html&gt;</code></pre>\n      <p>\n        サーバも、ビルドも、<code>npm install</code> も要りません。<br />\n        <code>total</code> に代入している行はありません。<b>導出しているだけ</b>なので、更新漏れが起きません。\n      </p>\n\n      <h2 id=\"one\" class=\"anchor\">増えた概念は1つだけ</h2>\n      <pre><code>$$(<span class=\"tok-s\">\"#total\"</span>).text(<span class=\"tok-s\">\"1,100\"</span>);  <span class=\"tok-c\">// 値を渡す    → その瞬間だけ入る（jQuery と同じ）</span>\n$$(<span class=\"tok-s\">\"#total\"</span>).text(total);      <span class=\"tok-c\">// state を渡す → 以後ずっと自動で追いかける ← これだけが新しい</span></code></pre>\n      <p>関数を渡すと、その中で読んだ状態を自動で追跡します。</p>\n      <pre><code>$$(<span class=\"tok-s\">\"#label\"</span>).text(() =&gt; <span class=\"tok-s\">`${count()}個 / ${total()}円`</span>);</code></pre>\n\n      <h2 id=\"selector\" class=\"anchor\">セレクタと @ 略記</h2>\n      <p>\n        <b>id も class も今まで通り使えます。HTML を変えられない現場でも、そのまま動きます。</b><br />\n        <code>data-brg</code> は<b>推奨ですが、必須ではありません</b>。HTML を触れるなら、こちらの方が壊れにくくなります。\n        <code>@</code> はその属性の省略記法です。\n      </p>\n      <pre><code>$$(<span class=\"tok-s\">\"#total\"</span>)   <span class=\"tok-c\">// id=\"total\"</span>\n$$(<span class=\"tok-s\">\".total\"</span>)   <span class=\"tok-c\">// class=\"total\"</span>\n$$(<span class=\"tok-s\">\"@total\"</span>)   <span class=\"tok-c\">// data-brg=\"total\"  ← [data-brg=\"total\"] の略記</span>\n$$(<span class=\"tok-s\">\"@list @row\"</span>)         <span class=\"tok-c\">// 組み合わせもできる</span>\n$$(<span class=\"tok-s\">\"@list\"</span>).find(<span class=\"tok-s\">\"@row\"</span>)  <span class=\"tok-c\">// find / closest / 委譲セレクタでも使える</span></code></pre>\n      <p>\n        <code>class</code> は見た目のためのものなので、デザイナーが変えます。それを JS が掴んでいると壊れます。\n        <b>掴む名前を <code>data-brg</code> に分ければ、class をいくら変えても JS は壊れません。</b>\n        属性名は <code>$$.attr = \"data-ui\"</code> で変更できます。\n      </p>\n\n      <!-- ============ まず4語 ============ -->\n      <h2 id=\"state\" class=\"anchor\">state</h2>\n      <p>読み書きの規約は jQuery と同じ（引数なしで読む・ありで書く）。</p>\n      <pre><code><span class=\"tok-k\">const</span> count = $$.<span class=\"tok-f\">state</span>(0);\n\ncount()            <span class=\"tok-c\">// 読む</span>\ncount(5)           <span class=\"tok-c\">// 書く</span>\ncount(n =&gt; n + 1)  <span class=\"tok-c\">// 更新</span>\n<span class=\"tok-s\">`${count}`</span>         <span class=\"tok-c\">// 補間もできる（count > 3 のような比較も）</span>\ncount.peek()       <span class=\"tok-c\">// 購読せずに覗く</span></code></pre>\n      <p>要素に結びつけることもできます。側面は要素から推論されます。</p>\n      <pre><code><span class=\"tok-k\">const</span> label = $$(<span class=\"tok-s\">\"#total\"</span>).state(0);        <span class=\"tok-c\">// span → textContent</span>\n<span class=\"tok-k\">const</span> name  = $$(<span class=\"tok-s\">\"#name\"</span>).state(<span class=\"tok-s\">\"\"</span>);       <span class=\"tok-c\">// input → value（双方向）</span>\n<span class=\"tok-k\">const</span> agree = $$(<span class=\"tok-s\">\"#agree\"</span>).state(<span class=\"tok-k\">false</span>);   <span class=\"tok-c\">// checkbox → checked（双方向）</span>\n<span class=\"tok-k\">const</span> src   = $$(<span class=\"tok-s\">\"#img\"</span>).state(url, <span class=\"tok-s\">\"attr:src\"</span>);  <span class=\"tok-c\">// 明示もできる</span>\n<span class=\"tok-k\">const</span> now   = $$(<span class=\"tok-s\">\"#total\"</span>).state();           <span class=\"tok-c\">// 引数なし → DOM の現在値が初期値</span></code></pre>\n      <p class=\"muted\">側面: <code>value</code> / <code>checked</code> / <code>text</code> / <code>html</code> /\n        <code>attr:名前</code> / <code>class:名前</code> / <code>css:プロパティ</code></p>\n\n      <h2 id=\"computed\" class=\"anchor\">computed</h2>\n      <p>依存は自動追跡。読まれるまで計算しません。結果が変わらなければ画面も触りません。</p>\n      <pre><code><span class=\"tok-k\">const</span> total  = $$.<span class=\"tok-f\">computed</span>(() =&gt; items().reduce((s, i) =&gt; s + i.price, 0));\n<span class=\"tok-k\">const</span> isFree = $$.<span class=\"tok-f\">computed</span>(() =&gt; total() &gt;= 5000);\n<span class=\"tok-k\">const</span> label  = $$.<span class=\"tok-f\">computed</span>(() =&gt; <span class=\"tok-s\">`${items().length}点 / ${total()}円`</span>);</code></pre>\n      <p>書き込もうとすると例外になります（読み取り専用）。</p>\n\n      <h2 id=\"when\" class=\"anchor\">when</h2>\n      <pre><code>$$(<span class=\"tok-s\">\"#error\"</span>).when(hasError);                    <span class=\"tok-c\">// display の出し入れ</span>\n$$(<span class=\"tok-s\">\"#modal\"</span>).when(open, { detach: <span class=\"tok-k\">true</span> });    <span class=\"tok-c\">// 偽なら DOM から外す</span>\n$$(<span class=\"tok-s\">\"#free\"</span>).when(() =&gt; qty() &gt;= 3);              <span class=\"tok-c\">// 関数でも書ける</span></code></pre>\n      <div class=\"note\">\n        <p style=\"margin:0\"><b>見せてはいけないものは <code>detach: true</code> を使ってください。</b>\n          CSS で隠す方式は、class 名のタイポや CSS の1行削除で<b>見えてしまう側</b>に倒れます。\n          DOM から外せば CSS に依存しません。</p>\n      </div>\n\n      <h2 id=\"repeat\" class=\"anchor\">repeat</h2>\n      <p>行の DOM を使い回すので、<b>入力途中の文字・フォーカス・スクロール位置が飛びません</b>。</p>\n      <pre><code>&lt;ul id=<span class=\"tok-s\">\"list\"</span>&gt;&lt;/ul&gt;\n&lt;template id=<span class=\"tok-s\">\"row\"</span>&gt;&lt;li&gt;&lt;span class=<span class=\"tok-s\">\"title\"</span>&gt;&lt;/span&gt;&lt;input class=<span class=\"tok-s\">\"memo\"</span>&gt;&lt;/li&gt;&lt;/template&gt;\n\n$$(<span class=\"tok-s\">\"#list\"</span>).repeat(todos, {\n  key: (t) =&gt; t.id,             <span class=\"tok-c\">// 一意な値。省略すると位置(index)になる</span>\n  tpl: <span class=\"tok-s\">\"#row\"</span>,                <span class=\"tok-c\">// &lt;template&gt; を雛形にする</span>\n  render: ($row, t) =&gt; {        <span class=\"tok-c\">// 中身はいつもの jQuery</span>\n    $row.find(<span class=\"tok-s\">\".title\"</span>).text(t.title);\n  },\n});</code></pre>\n      <p>サーバーが出力済みの一覧を乗っ取ることもできます（HTML を1文字も変えません）。</p>\n      <pre><code>$$(<span class=\"tok-s\">\"#list\"</span>).repeat(rows, { from: <span class=\"tok-s\">\"li\"</span>, key: (r) =&gt; r.id, render: … });</code></pre>\n      <p>簡単な行なら文字列でも書けます。</p>\n      <pre><code>$$(<span class=\"tok-s\">\"#list\"</span>).repeat(todos, (t) =&gt; <span class=\"tok-s\">`&lt;li&gt;${t.title}&lt;/li&gt;`</span>);</code></pre>\n      <p class=\"muted\">\n        <code>&lt;table&gt;</code> の <code>&lt;tr&gt;</code> や <code>&lt;select&gt;</code> の <code>&lt;option&gt;</code>\n        でも動きます（テスト済み）。\n        <code>&lt;select&gt;</code> では項目を増やしても<b>選択中の値が消えません</b>。<br />\n        キーが重複していると警告します。\n      </p>\n\n      <!-- ============ 知っている jQuery ============ -->\n      <h2 id=\"dollar\" class=\"anchor\">$$( ) が受け取れるもの</h2>\n      <pre><code>$$(<span class=\"tok-s\">\"#id\"</span>) $$(<span class=\"tok-s\">\".class\"</span>) $$(<span class=\"tok-s\">\"@name\"</span>) $$(<span class=\"tok-s\">\"a[href]\"</span>)   <span class=\"tok-c\">// セレクタ</span>\n$$(<span class=\"tok-s\">\"&lt;li&gt;x&lt;/li&gt;\"</span>)      <span class=\"tok-c\">// HTML 生成</span>\n$$(el) $$(nodeList) $$([el1, el2]) $$($$(…))\n$$(document) $$(window)  <span class=\"tok-c\">// イベント用</span>\n$$(<span class=\"tok-k\">function</span> () { … })   <span class=\"tok-c\">// DOM ready</span></code></pre>\n      <p class=\"muted\">プロパティ: <code>.length</code> / <code>.el</code>（先頭の要素） / <code>.els</code>（配列）</p>\n\n      <h2 id=\"content\" class=\"anchor\">text / html / val / attr / prop / css</h2>\n      <p>引数なしで読む・値で書く・state で束縛する、の3態です。</p>\n      <pre><code>$$(<span class=\"tok-s\">\"#t\"</span>).text()            <span class=\"tok-c\">// 読む</span>\n$$(<span class=\"tok-s\">\"#t\"</span>).text(<span class=\"tok-s\">\"完了\"</span>)      <span class=\"tok-c\">// 書く</span>\n$$(<span class=\"tok-s\">\"#t\"</span>).text(total)        <span class=\"tok-c\">// 束縛（以後ずっと追従）</span></code></pre>\n      <p><code>text()</code> は「値 → 加工 → 形」の順に引数を足せます。</p>\n      <pre><code>$$(<span class=\"tok-s\">\"#n\"</span>).text(count)                        <span class=\"tok-c\">// 3</span>\n$$(<span class=\"tok-s\">\"#n\"</span>).text(count, <span class=\"tok-s\">\"件\"</span>)                  <span class=\"tok-c\">// 3件</span>\n$$(<span class=\"tok-s\">\"#n\"</span>).text(count, <span class=\"tok-s\">\"残り{}件\"</span>)            <span class=\"tok-c\">// 残り3件</span>\n$$(<span class=\"tok-s\">\"#n\"</span>).text(total, $$.money, <span class=\"tok-s\">\"円\"</span>)       <span class=\"tok-c\">// 23,800円</span>\n$$(<span class=\"tok-s\">\"#n\"</span>).text(count, (v) =&gt; v * 1.1, <span class=\"tok-s\">\"円\"</span>)  <span class=\"tok-c\">// 加工してから</span></code></pre>\n      <p>その他も同じ形です。</p>\n      <pre><code>$$(<span class=\"tok-s\">\"#img\"</span>).attr(<span class=\"tok-s\">\"src\"</span>, url);\n$$(<span class=\"tok-s\">\"#btn\"</span>).prop(<span class=\"tok-s\">\"disabled\"</span>, busy);\n$$(<span class=\"tok-s\">\"#q\"</span>).val(keyword);                   <span class=\"tok-c\">// 双方向</span>\n$$(<span class=\"tok-s\">\"#bar\"</span>).css(<span class=\"tok-s\">\"width\"</span>, () =&gt; <span class=\"tok-s\">`${pct()}%`</span>);\n$$(<span class=\"tok-s\">\"#row\"</span>).data(<span class=\"tok-s\">\"id\"</span>, id);\n$$(<span class=\"tok-s\">\"#box\"</span>).addClass(<span class=\"tok-s\">\"a b\"</span>).removeClass(<span class=\"tok-s\">\"c\"</span>).hasClass(<span class=\"tok-s\">\"a\"</span>);\n$$(<span class=\"tok-s\">\"#box\"</span>).toggleClass(<span class=\"tok-s\">\"is-open\"</span>, open);   <span class=\"tok-c\">// 真偽の state で付け外し</span></code></pre>\n\n      <h2 id=\"uistate\" class=\"anchor\">UI 状態（selected / disabled …）</h2>\n      <p>\n        <code>.addClass(\"active\")</code> の代わりに「<b>UI がどういう状態か</b>」を書けます。\n        ARIA 属性と <code>data-</code> 属性が<b>同時に</b>付くので、CSS も支援技術も同じ状態を見ます。\n      </p>\n      <pre><code>$$(<span class=\"tok-s\">\"#tab\"</span>).selected(isCurrent);   <span class=\"tok-c\">// aria-selected + [data-selected]</span>\n$$(<span class=\"tok-s\">\"#head\"</span>).expanded(isOpen);    <span class=\"tok-c\">// aria-expanded（false も明示）+ [data-expanded]</span>\n$$(<span class=\"tok-s\">\"#mail\"</span>).invalid(hasError);   <span class=\"tok-c\">// aria-invalid + [data-invalid]</span>\n$$(<span class=\"tok-s\">\"#list\"</span>).busy(loading);       <span class=\"tok-c\">// aria-busy + [data-busy]</span>\n$$(<span class=\"tok-s\">\"#save\"</span>).disabled(sending);   <span class=\"tok-c\">// 本物の disabled（a タグなら aria-disabled）</span></code></pre>\n      <p>引数なしで現在値を読めます（<code>$$(\"#save\").disabled()</code>）。静的な真偽値も渡せます。</p>\n\n      <h2 id=\"mode\" class=\"anchor\">mode / toggleAttr / vars</h2>\n      <p><b>排他的な状態</b>は属性1つで表します。class は「消し忘れ」で2つ付きますが、属性は構造的に1つだけです。</p>\n      <pre><code>$$(<span class=\"tok-s\">\"#form\"</span>).mode(() =&gt; sending() ? <span class=\"tok-s\">\"sending\"</span> : failed() ? <span class=\"tok-s\">\"error\"</span> : <span class=\"tok-s\">\"ready\"</span>);\n<span class=\"tok-c\">// → &lt;form data-mode=\"sending\"&gt;    CSS: [data-mode=\"sending\"] .spinner { display:block }</span></code></pre>\n      <p>真偽で属性の有無を切り替えます（<code>attr(name, false)</code> は文字列 <code>\"false\"</code> が入る罠があります）。</p>\n      <pre><code>$$(<span class=\"tok-s\">\"#panel\"</span>).toggleAttr(<span class=\"tok-s\">\"data-open\"</span>, isOpen);   <span class=\"tok-c\">// 偽なら属性そのものが消える</span></code></pre>\n      <p>CSS カスタムプロパティに値を流します。計算・アニメ・レスポンシブは CSS の仕事のまま残ります。</p>\n      <pre><code>$$(<span class=\"tok-s\">\"#bar\"</span>).vars({ progress: () =&gt; <span class=\"tok-s\">`${pct()}%`</span> });\n<span class=\"tok-c\">// → style=\"--progress: 60%\"       CSS: .fill { width: var(--progress) }</span></code></pre>\n\n      <h2 id=\"traverse\" class=\"anchor\">走査</h2>\n      <pre><code>$$(<span class=\"tok-s\">\"#a\"</span>).find(<span class=\"tok-s\">\".x\"</span>) .closest(<span class=\"tok-s\">\"@row\"</span>) .parent() .children(<span class=\"tok-s\">\"li\"</span>)\n      .first() .last() .is(<span class=\"tok-s\">\".on\"</span>) .each((el, i) =&gt; { … })</code></pre>\n      <p class=\"muted\">\n        <code>next</code> / <code>prev</code> / <code>siblings</code> / <code>eq</code> / <code>index</code>\n        は<b>ありません</b>。\n        構造に依存して静かに壊れるためです（<a href=\"#removed\">持たないもの</a>）。\n      </p>\n\n      <h2 id=\"events\" class=\"anchor\">イベント</h2>\n      <pre><code>$$(<span class=\"tok-s\">\"#b\"</span>).on(<span class=\"tok-s\">\"click\"</span>, fn);\n$$(<span class=\"tok-s\">\"#list\"</span>).on(<span class=\"tok-s\">\"click\"</span>, <span class=\"tok-s\">\"@row\"</span>, fn);   <span class=\"tok-c\">// 委譲（後から追加された要素にも効く）</span>\n$$(<span class=\"tok-s\">\"#b\"</span>).on(<span class=\"tok-s\">\"click focus\"</span>, fn);         <span class=\"tok-c\">// 複数</span>\n$$(<span class=\"tok-s\">\"#b\"</span>).off(<span class=\"tok-s\">\"click\"</span>);\n$$(<span class=\"tok-s\">\"#b\"</span>).click(fn);  $$(<span class=\"tok-s\">\"#b\"</span>).click();   <span class=\"tok-c\">// 短縮（引数ありでバインド、無しで発火）</span></code></pre>\n      <p class=\"muted\">\n        短縮: <code>click</code> <code>dblclick</code> <code>change</code> <code>submit</code> <code>input</code>\n        <code>keydown</code> <code>keyup</code> <code>focus</code> <code>blur</code> <code>mousedown</code>\n        <code>mouseup</code> <code>mouseenter</code> <code>mouseleave</code> <code>scroll</code><br />\n        イベント名前空間（<code>click.myui</code>）はありません。後片付けは <code>scope</code> が上位互換です。\n      </p>\n\n      <h2 id=\"manip\" class=\"anchor\">追加・削除</h2>\n      <pre><code>$$(<span class=\"tok-s\">\"#list\"</span>).append(<span class=\"tok-s\">\"&lt;li&gt;x&lt;/li&gt;\"</span>);   <span class=\"tok-c\">// 文字列 / ノード / $$(…) / 配列</span>\n$$(<span class=\"tok-s\">\"#list\"</span>).empty();\n$$(<span class=\"tok-s\">\"#row\"</span>).remove();      <span class=\"tok-c\">// 張った購読も一緒に片付ける</span>\n$$(<span class=\"tok-s\">\"#row\"</span>).dispose();     <span class=\"tok-c\">// 要素は残して購読だけ切る</span></code></pre>\n\n      <!-- ============ 困ったら4語 ============ -->\n      <h2 id=\"form\" class=\"anchor\">form（フォームの事故）</h2>\n      <p>HTML の <code>required</code> / <code>type=\"email\"</code> / <code>pattern</code> / <code>min</code>\n        を読むので、<b>HTML を1文字も変えずに</b>使えます。</p>\n      <pre><code><span class=\"tok-k\">const</span> f = $$(<span class=\"tok-s\">\"#signup\"</span>).form();          <span class=\"tok-c\">// HTML の属性から</span>\n\n<span class=\"tok-k\">const</span> f = $$(<span class=\"tok-s\">\"#signup\"</span>).form({           <span class=\"tok-c\">// JS 側で足す（HTML の分と合成される）</span>\n  company: { required: <span class=\"tok-k\">true</span>, when: () =&gt; plan() === <span class=\"tok-s\">\"corp\"</span> },\n  confirm: { same: <span class=\"tok-s\">\"password\"</span> },\n  tel:     { pattern: /^0\\d{9,10}$/, message: <span class=\"tok-s\">\"電話番号の形式が違います\"</span> },\n  age:     { min: 18, message: <span class=\"tok-s\">\"18歳以上のみお申し込みいただけます\"</span> },\n});</code></pre>\n      <p>状態は全部 state なので、そのまま画面に繋げられます。</p>\n      <pre><code>$$(<span class=\"tok-s\">\"#count\"</span>).text(f.errorCount, <span class=\"tok-s\">\"件の未入力\"</span>);\n$$(<span class=\"tok-s\">\"#msg\"</span>).text(f.firstError);\n$$(<span class=\"tok-s\">\"#mail-err\"</span>).text(f.error(<span class=\"tok-s\">\"email\"</span>));\n$$(<span class=\"tok-s\">\"#alert\"</span>).when(f.hasErrors);\n$$(<span class=\"tok-s\">\"#save\"</span>).disabled(f.submitting);\n\nf.submit(<span class=\"tok-k\">async</span> (values) =&gt; {          <span class=\"tok-c\">// 二重送信は自動で防がれる</span>\n  <span class=\"tok-k\">await</span> fetch(<span class=\"tok-s\">\"/api/signup\"</span>, { method: <span class=\"tok-s\">\"POST\"</span>, body: JSON.stringify(values) });\n});</code></pre>\n      <div class=\"note\">\n        <p style=\"margin:0 0 6px;font-weight:700\"><i class=\"fa-solid fa-eye-slash\"></i> 見えていないフィールドは検証しません</p>\n        <p style=\"margin:0\">\n          HTML5 標準検証は <code>display:none</code> の <code>required</code> でも送信をブロックしますが、\n          フォーカスできない要素にはエラーを表示できません。「押しても何も起きない」状態になり、離脱します。<br />\n          bridgey は <code>novalidate</code> を立てて主権を取り、<b>いま見えているフィールドだけ</b>を毎回判定します。<br />\n          既定では<b>送信ボタンを無効化しません</b>（押せて、押したら理由を表示して該当箇所へ飛ばします）。\n        </p>\n      </div>\n      <p class=\"muted\">\n        ルール: <code>required</code>（関数も可） <code>email</code> <code>pattern</code> <code>min</code> <code>max</code>\n        <code>minLength</code> <code>maxLength</code> <code>same</code> <code>when</code> <code>message</code>\n        <code>validate</code><br />\n        状態: <code>values</code> <code>errors</code> <code>errorCount</code> <code>hasErrors</code>\n        <code>firstError</code>\n        <code>errorList</code> <code>error(name)</code> <code>valid</code> <code>dirty</code> <code>submitting</code>\n        <code>submitted</code><br />\n        操作: <code>submit(handler)</code> <code>submit()</code> <code>validate()</code> <code>reset(values?)</code>\n        <code>focusFirstError()</code> <code>refresh()</code><br />\n        オプション: <code>disableSubmit</code> <code>errorAttr</code> <code>validateHidden</code> <code>autoErrorSlot</code>\n      </p>\n\n      <h2 id=\"group\" class=\"anchor\">group（選択）</h2>\n      <p>ラジオ / チェックボックス群を1つの state にします。選択状態の二重管理（<code>checked</code> と <code>.active</code>）が消えます。</p>\n      <pre><code><span class=\"tok-k\">const</span> plan    = $$(<span class=\"tok-s\">\"#plan input\"</span>).group();     <span class=\"tok-c\">// ラジオ → 選ばれている value</span>\n<span class=\"tok-k\">const</span> options = $$(<span class=\"tok-s\">\"#opt input\"</span>).group();      <span class=\"tok-c\">// チェックボックス → value の配列</span>\n\n<span class=\"tok-k\">const</span> total = $$.<span class=\"tok-f\">computed</span>(() =&gt; options().reduce((s, k) =&gt; s + PRICE[k], 0));</code></pre>\n\n      <h2 id=\"component\" class=\"anchor\">component（common.js）</h2>\n      <p>\n        全ページで読まれる <code>common.js</code> に「手続き」を書くと、要素が無いページでも走り、\n        1箇所の undefined で以降が全部死にます。<b>「登録」だけを書く</b>形にすれば、その両方が消えます。\n      </p>\n      <pre><code>$$.<span class=\"tok-f\">component</span>(<span class=\"tok-s\">\"tabs\"</span>, ($el, props, ctx) =&gt; {\n  <span class=\"tok-k\">const</span> current = $$.<span class=\"tok-f\">state</span>(props.start ?? <span class=\"tok-s\">\"a\"</span>);\n  $el.find(<span class=\"tok-s\">\"@tab\"</span>).each((el) =&gt; $$(el)\n    .click(() =&gt; current(el.dataset.tab))\n    .selected(() =&gt; current() === el.dataset.tab));\n  $el.find(<span class=\"tok-s\">\"@pane\"</span>).each((el) =&gt; $$(el).when(() =&gt; current() === el.dataset.tab));\n\n  <span class=\"tok-k\">const</span> id = setInterval(tick, 1000);\n  ctx.scope.add(() =&gt; clearInterval(id));   <span class=\"tok-c\">// 要素が消えたら止まる</span>\n});</code></pre>\n      <pre><code>&lt;ul data-component=<span class=\"tok-s\">\"tabs\"</span> data-start=<span class=\"tok-s\">\"b\"</span>&gt;…&lt;/ul&gt;</code></pre>\n      <ul>\n        <li><b>要素が無いページでは1行も実行されません</b>（存在チェックの <code>if</code> が不要）</li>\n        <li><b>1つの初期化が失敗しても、他は動き続けます</b>（失敗した部品名と、生きている部品名を通知）</li>\n        <li><b>Ajax で後から追加された要素にも自動で適用</b>され、消えたら自動で片付きます</li>\n        <li><code>data-*</code> が <code>props</code> になります（<code>\"5\"</code>→5、<code>\"007\"</code>は文字列のまま）</li>\n      </ul>\n      <p class=\"muted\">\n        <code>$$.mount(root?)</code> で手動走査、<code>$$.unmount(root?)</code> で破棄、\n        <code>$$(\"#x\").component(\"tabs\", props)</code> で明示適用。属性名は <code>$$.componentAttr(\"data-...\")</code>。\n      </p>\n\n      <h2 id=\"resource\" class=\"anchor\">resource / action（通信）</h2>\n      <p>\n        同じ JSON を何度も取り、応答の順序が入れ替わって<b>古い金額が残る</b>——これを構造的に潰します。\n        前のリクエストは <code>AbortController</code> で中断し、それでも解決した古い応答は<b>世代番号で捨てます</b>。\n      </p>\n      <pre><code><span class=\"tok-k\">const</span> rows = $$.<span class=\"tok-f\">resource</span>(() =&gt; fetch(<span class=\"tok-s\">\"/data.json\"</span>).then(r =&gt; r.json()));\n$$(<span class=\"tok-s\">\"#spinner\"</span>).when(rows.loading);\n$$(<span class=\"tok-s\">\"#error\"</span>).when(() =&gt; !!rows.error());\n\n<span class=\"tok-c\">// 入力に追従（前の取得は自動で中断される）</span>\n<span class=\"tok-k\">const</span> q    = $$(<span class=\"tok-s\">\"#q\"</span>).state(<span class=\"tok-s\">\"\"</span>);\n<span class=\"tok-k\">const</span> hits = $$.<span class=\"tok-f\">resource</span>(q, (word, signal) =&gt;\n  fetch(<span class=\"tok-s\">`/search?q=${word}`</span>, { signal }).then(r =&gt; r.json()), { debounce: 300 });</code></pre>\n      <p>二重送信しないアクション。失敗しても <code>running</code> は必ず戻ります（永久 disabled になりません）。</p>\n      <pre><code><span class=\"tok-k\">const</span> save = $$.<span class=\"tok-f\">action</span>(<span class=\"tok-k\">async</span> () =&gt; { <span class=\"tok-k\">await</span> fetch(<span class=\"tok-s\">\"/api/save\"</span>, { … }); });\n$$(<span class=\"tok-s\">\"#save\"</span>).click(save).disabled(save.running);\n$$(<span class=\"tok-s\">\"#save-error\"</span>).when(() =&gt; !!save.error());</code></pre>\n      <p class=\"muted\">\n        <code>resource</code>: <code>data</code> <code>loading</code> <code>error</code> <code>refetch()</code>\n        <code>abort()</code> <code>ready()</code> / オプション <code>debounce</code> <code>keepPrevious</code>\n        <code>immediate</code>\n      </p>\n\n      <!-- ============ 事故を防ぐしくみ ============ -->\n      <h2 id=\"warnings\" class=\"anchor\">警告</h2>\n      <p>jQuery は0件でも黙ります。bridgey は「確実にバグ」のときだけ鳴ります。</p>\n      <pre><code>[bridgey] $$(\".price\") が0件でした。text() を結びつけられません。\n  HTML が変わった可能性があります(class 名の変更・要素の削除・読み込み順)。\n  → 壊れにくくするには data 属性で結びつけてください:\n     &lt;span data-brg=\"price\"&gt;&lt;/span&gt;  →  $$(\"@price\")</code></pre>\n      <ul>\n        <li><b>0件で束縛しようとした</b>（命令的な操作の0件は無害なので黙ります）</li>\n        <li><b>CSS に無い class 名</b>で表示制御しようとした（似ている名前を提示）</li>\n        <li><b>repeat のキーが重複</b>している</li>\n        <li><b>component の初期化に失敗</b>した（生きている部品名も知らせる）</li>\n        <li><b>印を書いたのに <code>$$.bind()</code> されていない</b>要素がある</li>\n        <li><b>削除した API を呼んだ</b>（代わりの書き方を提示して例外）</li>\n      </ul>\n      <p class=\"muted\">本番でうるさければ <code>$$.warn = false</code>。class 名の検査だけ切るなら <code>$$.warnUnknownClass = false</code>。\n      </p>\n\n      <h2 id=\"hints\" class=\"anchor\">ヒント</h2>\n      <p>22個ある語を全部覚えなくても、<b>必要になった場面で案内が出ます</b>（警告とは別カテゴリ）。</p>\n      <pre><code>[bridgey] addClass(\"active\") で状態を表しているようです。\n          → .selected(state) が使えます: aria-selected も一緒に付き、\n            他の要素から消し忘れることもありません\n          (このヒントは $$.hints = false で止められます)</code></pre>\n      <p class=\"muted\">\n        <code>css(\"display\", …)</code> → <code>when()</code> ／ <code>attr(name, false)</code> →\n        <code>toggleAttr()</code> ／\n        <code>html(一覧)</code> → <code>repeat()</code> も案内します。\n      </p>\n\n      <h2 id=\"ime\" class=\"anchor\">日本語入力</h2>\n      <p>\n        電話番号や郵便番号の自動整形、全角→半角、カナ変換——<b>入力しながら値を書き戻す</b>処理は日本のフォームで極めてよくあります。\n        漢字変換の最中に書き戻すと、変換候補が消える・確定できない・文字が化けます。\n      </p>\n      <p>\n        bridgey は <code>compositionstart</code> 〜 <code>compositionend</code> の間、\n        <b>DOM→state と state→DOM の両方を止め</b>、確定した瞬間に一度だけ同期します。\n        フォームの検証も変換中は走りません（「にほん」の途中で赤くなりません）。\n      </p>\n\n      <!-- ============ 配布と設定 ============ -->\n      <h2 id=\"dist\" class=\"anchor\">&lt;script&gt; と npm</h2>\n      <pre><code><span class=\"tok-c\">&lt;!-- CDN。読み込むと window.$$ が生える --&gt;</span>\n&lt;script src=<span class=\"tok-s\">\"https://cdn.jsdelivr.net/npm/bridgey@2\"</span>&gt;&lt;/script&gt;\n\n<span class=\"tok-c\">// npm（型が付く）</span>\n<span class=\"tok-k\">import</span> { $$ } <span class=\"tok-k\">from</span> <span class=\"tok-s\">\"bridgey\"</span>;</code></pre>\n      <p class=\"muted\">\n        <code>dist/bridgey.js</code>（min）/ <code>dist/bridgey.dev.js</code>（非min・警告が読みやすい）/\n        <code>dist/bridgey.esm.js</code>（npm）。TypeScript で書かれているので型定義は実装とズレません。\n      </p>\n\n      <h2 id=\"global-name\" class=\"anchor\">グローバル名を変える</h2>\n      <p><code>&lt;script&gt;</code> タグの<b>1箇所</b>だけで変えられます。</p>\n      <pre><code>&lt;script src=<span class=\"tok-s\">\"…/bridgey@2\"</span>&gt;&lt;/script&gt;                       <span class=\"tok-c\">// $$</span>\n&lt;script src=<span class=\"tok-s\">\"…/bridgey@2\"</span> data-global=<span class=\"tok-s\">\"$\"</span>&gt;&lt;/script&gt;      <span class=\"tok-c\">// $</span>\n&lt;script src=<span class=\"tok-s\">\"…/bridgey@2\"</span> data-global=<span class=\"tok-s\">\"$$$\"</span>&gt;&lt;/script&gt;    <span class=\"tok-c\">// $$$</span>\n&lt;script src=<span class=\"tok-s\">\"…/bridgey@2\"</span> data-global=<span class=\"tok-s\">\"$_$\"</span>&gt;&lt;/script&gt;    <span class=\"tok-c\">// $_$</span>\n&lt;script src=<span class=\"tok-s\">\"…/bridgey@2\"</span> data-global=<span class=\"tok-s\">\"brg,$$\"</span>&gt;&lt;/script&gt; <span class=\"tok-c\">// 両方</span></code></pre>\n      <p>\n        <code>$$</code> が既に使われていたら（Prototype.js など）、<b>勝手に別名へ逃がさず</b>警告します。\n        サイトによって名前が変わると、コピーしたコードが動かない原因が分からなくなるからです。\n        <code>window.bridgey</code> からは常に使えます。<code>bridgey.noConflict()</code> で元に戻せます。\n      </p>\n      <p class=\"muted\">jQuery と同じページ・同じ要素で共存できます（<code>$</code> は奪いません）。</p>\n\n      <h2 id=\"config\" class=\"anchor\">設定と補助</h2>\n      <pre><code>$$.attr = <span class=\"tok-s\">\"data-brg\"</span>;      <span class=\"tok-c\">// @ が解決する属性名</span>\n$$.warn = <span class=\"tok-k\">true</span>;             <span class=\"tok-c\">// 事故の警告</span>\n$$.hints = <span class=\"tok-k\">true</span>;            <span class=\"tok-c\">// より良い書き方の提案</span>\n$$.warnUnknownClass = <span class=\"tok-k\">true</span>; <span class=\"tok-c\">// true | \"all\" | false</span>\n$$.warnSink = (m) =&gt; …;      <span class=\"tok-c\">// 警告の出口を差し替える</span>\n$$.version                   <span class=\"tok-c\">// \"2.0.0-beta.1\"</span></code></pre>\n      <pre><code><span class=\"tok-k\">await</span> $$.tick();            <span class=\"tok-c\">// DOM 反映を待つ</span>\n$$.batch(() =&gt; { … });       <span class=\"tok-c\">// まとめて1回</span>\n$$.untrack(() =&gt; … );        <span class=\"tok-c\">// 購読を張らずに読む</span>\n$$.effect(() =&gt; … );         <span class=\"tok-c\">// DOM 以外に反映したいとき（戻り値で解除）</span>\n<span class=\"tok-k\">const</span> s = $$.scope(() =&gt; …); s.dispose();   <span class=\"tok-c\">// 片付けの単位</span>\n$$.money(23800)              <span class=\"tok-c\">// \"23,800\"</span>\n$$.fn.myPlugin = <span class=\"tok-k\">function</span> () { … };       <span class=\"tok-c\">// プラグイン拡張口</span></code></pre>\n      <p class=\"muted\">\n        状態の更新は自動でまとまります（同一フレームの書き込みを rAF で1回に）。\n        <code>.text()</code> を1000回呼んでも reflow は1回です。\n      </p>\n\n      <!-- ============ その他 ============ -->\n      <h2 id=\"removed\" class=\"anchor\">持たないもの</h2>\n      <p>呼ぶと、代わりの書き方を教えて例外になります。黙って <code>undefined</code> にはなりません。</p>\n      <pre><code>$$(<span class=\"tok-s\">\"#row\"</span>).next();\n<span class=\"tok-c\">// Error: [bridgey] next() は使えません。HTML の構造が変わると壊れるため v2 では\n//        提供していません(要素を1つ挟むだけで、例外も出ないまま静かに動かなくなります)。\n//        → 構造ではなく名前で引いてください: $$(this).closest(\"@row\").find(\"@price\")</span></code></pre>\n      <table class=\"compare\" style=\"width:100%;border-collapse:collapse;font-size:13.5px;margin-top:14px\">\n        <thead>\n          <tr>\n            <th style=\"text-align:left;padding:8px 10px\">持たないもの</th>\n            <th style=\"text-align:left;padding:8px 10px\">代わりに</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td style=\"padding:8px 10px\"><code>fadeIn</code> / <code>slideToggle</code> / <code>animate</code></td>\n            <td style=\"padding:8px 10px\">CSS <code>transition</code> ＋ <code>.toggleClass(\"is-open\", state)</code></td>\n          </tr>\n          <tr>\n            <td style=\"padding:8px 10px\"><code>show</code> / <code>hide</code> / <code>toggle</code></td>\n            <td style=\"padding:8px 10px\"><code>when(state)</code></td>\n          </tr>\n          <tr>\n            <td style=\"padding:8px 10px\"><code>$.ajax</code> / <code>get</code> / <code>post</code></td>\n            <td style=\"padding:8px 10px\"><code>fetch()</code>、競合制御は <code>$$.resource()</code></td>\n          </tr>\n          <tr>\n            <td style=\"padding:8px 10px\"><code>$.extend</code> / <code>each</code> / <code>map</code> /\n              <code>trim</code></td>\n            <td style=\"padding:8px 10px\"><code>{...a, ...b}</code> / <code>for...of</code> / <code>Array#map</code> /\n              <code>String#trim</code></td>\n          </tr>\n          <tr>\n            <td style=\"padding:8px 10px\"><code>serialize</code> / <code>serializeArray</code></td>\n            <td style=\"padding:8px 10px\"><code>new FormData(form)</code>、検証は <code>form()</code></td>\n          </tr>\n          <tr>\n            <td style=\"padding:8px 10px\"><code>next</code> / <code>prev</code> / <code>siblings</code> / <code>eq</code>\n              / <code>index</code> / <code>parents</code></td>\n            <td style=\"padding:8px 10px\"><code>closest(\"@row\").find(\"@price\")</code></td>\n          </tr>\n          <tr>\n            <td style=\"padding:8px 10px\"><code>width</code> / <code>height</code> / <code>offset</code></td>\n            <td style=\"padding:8px 10px\"><code>getBoundingClientRect()</code></td>\n          </tr>\n          <tr>\n            <td style=\"padding:8px 10px\"><code>clone</code> / <code>before</code> / <code>after</code> /\n              <code>prepend</code> / <code>replaceWith</code> / <code>detach</code></td>\n            <td style=\"padding:8px 10px\"><code>repeat()</code> / <code>when(…, {detach:true})</code></td>\n          </tr>\n          <tr>\n            <td style=\"padding:8px 10px\"><code>one</code> / <code>trigger</code> / <code>hover</code></td>\n            <td style=\"padding:8px 10px\"><code>{ once: true }</code> / <code>dispatchEvent</code> /\n              <code>mouseenter</code>+<code>mouseleave</code></td>\n          </tr>\n          <tr>\n            <td style=\"padding:8px 10px\">ルーター / SPA 化</td>\n            <td style=\"padding:8px 10px\">URL の主権はサーバーに</td>\n          </tr>\n          <tr>\n            <td style=\"padding:8px 10px\">スコープ付きCSS / 仮想DOM / SSR</td>\n            <td style=\"padding:8px 10px\">入れません</td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"muted\" style=\"margin-top:12px\">\n        jQuery プラグイン（slick / DataTables 等）は bridgey では動きません。jQuery 本体と<b>併用</b>してください。\n      </p>\n\n      <h2 id=\"v1\" class=\"anchor\">v1 からの移行</h2>\n      <p>v2 は破壊的変更です。Svelte / Vue への依存は廃止しました。</p>\n      <pre><code><span class=\"tok-c\">// v1                                    v2</span>\nuseEngine(svelteEngine)              <span class=\"tok-c\">// 削除（エンジンの概念そのものが無い）</span>\nmount(Component, { target })         <span class=\"tok-c\">// 削除 → component() / repeat()</span>\nstate(0) → count.value               <span class=\"tok-c\">// $$.state(0) → count() / count(5)</span>\ncomputed(deps, fn)                   <span class=\"tok-c\">// $$.computed(fn)（依存は自動追跡）</span>\nbindText / bindClass / bindAttr      <span class=\"tok-c\">// .text(state) / .toggleClass(n, state) / .attr(n, state)</span>\n$$.get / $$.post                     <span class=\"tok-c\">// fetch() / $$.resource()</span>\n$$(<span class=\"tok-s\">\"#x\"</span>).val() が String サブクラス     <span class=\"tok-c\">// 普通の文字列（=== が期待通り動く）</span>\njQuery 共存は非サポート                 <span class=\"tok-c\">// 公式サポート</span></code></pre>\n    </main>\n  </div>\n</div>","tutorial":"<a id=\"top\"></a>\n<div class=\"wrap\">\n  <div class=\"layout\">\n    <aside class=\"toc\">\n      <div class=\"grp\">準備</div>\n      <a href=\"#setup\">1. 読み込む</a>\n\n      <div class=\"grp\">4語を覚える</div>\n      <a href=\"#step-state\">2. state — 状態を持つ</a>\n      <a href=\"#step-computed\">3. computed — 計算する</a>\n      <a href=\"#step-when\">4. when — 出し入れする</a>\n      <a href=\"#step-repeat\">5. repeat — 一覧を描く</a>\n\n      <div class=\"grp\">現場に入れる</div>\n      <a href=\"#step-form\">6. フォームの事故を止める</a>\n      <a href=\"#step-component\">7. common.js を安全にする</a>\n      <a href=\"#step-migrate\">8. 既存 jQuery と混ぜる</a>\n\n      <div class=\"grp\">仕上げ</div>\n      <a href=\"#step-warn\">9. 警告を読む</a>\n      <a href=\"#next\">次に読むもの</a>\n    </aside>\n\n    <main class=\"content\">\n      <h1>チュートリアル</h1>\n      <p class=\"muted\">\n        コピペして動かしながら進めてください。ビルドは要りません。<br />\n        <b>2〜5 の4語で8割書けます。</b>6以降は現場に入れるときの話です。\n      </p>\n\n      <h2 id=\"setup\" class=\"anchor\">1. 読み込む</h2>\n      <p>\n        <code>demo.html</code> という名前でファイルを1つ作って、これを丸ごと貼ってください。<br />\n        <b>そのままブラウザで開けば動きます。</b>以降はこのファイルの中身を書き換えていきます。\n      </p>\n      <pre><code>&lt;!doctype html&gt;\n&lt;html lang=\"ja\"&gt;\n&lt;head&gt;\n&lt;meta charset=\"utf-8\"&gt;\n&lt;title&gt;demo&lt;/title&gt;\n&lt;/head&gt;\n&lt;body&gt;\n\n&lt;p&gt;ここに作っていきます&lt;/p&gt;\n\n&lt;script src=\"https://cdn.jsdelivr.net/npm/bridgey@2\"&gt;&lt;/script&gt;\n&lt;script&gt;\n  console.log($$.version);   // 2.x が出れば読み込めています\n&lt;/script&gt;\n\n&lt;/body&gt;\n&lt;/html&gt;</code></pre>\n      <div class=\"note\">\n        <p style=\"margin:0\"><b>F12 でコンソールを開いておいてください。</b>\n          bridgey は間違いを黙って無視せず、直し方を添えて教えます。それがこのライブラリの主な機能です。</p>\n      </div>\n\n      <h2 id=\"step-state\" class=\"anchor\">2. state — 状態を持つ</h2>\n      <p>読み書きの規約は <code>.val()</code> と同じ。引数なしで読み、引数ありで書きます。</p>\n      <pre><code>&lt;p&gt;数量 &lt;span id=\"qty\"&gt;&lt;/span&gt;&lt;/p&gt;\n&lt;button id=\"inc\"&gt;＋&lt;/button&gt;\n\n&lt;script&gt;\n  const qty = $$.state(1);\n\n  $$(\"#qty\").text(qty);                  // ← state を渡すと、以後ずっと追従する\n  $$(\"#inc\").click(() => qty(n => n + 1));\n&lt;/script&gt;</code></pre>\n      <p>\n        <code>$$(\"#qty\").text(\"1\")</code> なら「その瞬間だけ入る」（jQuery と同じ）。\n        <b>state を渡したときだけ、ずっと追いかけます。</b>増えた概念はこれだけです。\n      </p>\n\n      <h2 id=\"step-computed\" class=\"anchor\">3. computed — 計算する</h2>\n      <p>合計・小計・表示するかどうか。<b>「代入する場所」を作らない</b>のが要点です。</p>\n      <pre><code>&lt;p&gt;合計 &lt;span id=\"total\"&gt;&lt;/span&gt; 円&lt;/p&gt;\n\n&lt;script&gt;\n  const qty   = $$.state(1);\n  const total = $$.computed(() => qty() * 1100);\n\n  $$(\"#total\").text(total, $$.money);    // 23,800 のように3桁区切り\n&lt;/script&gt;</code></pre>\n      <p>\n        <code>total</code> に代入している行はどこにもありません。だから\n        <b>「オプションを増やしたのに合計の更新を忘れた」が起きません。</b>\n        現場で最も多い金額事故がこれです。\n      </p>\n      <p>表示の形は「値 → 加工 → 形」の順に足せます。</p>\n      <pre><code>$$(\"#n\").text(qty, \"個\");                  // 3個\n$$(\"#n\").text(qty, \"残り{}個\");            // 残り3個\n$$(\"#n\").text(total, $$.money, \"円\");      // 23,800円</code></pre>\n\n      <h2 id=\"step-when\" class=\"anchor\">4. when — 出し入れする</h2>\n      <pre><code>&lt;p id=\"free\"&gt;3個以上で送料無料&lt;/p&gt;\n\n&lt;script&gt;\n  $$(\"#free\").when(() => qty() >= 3);\n&lt;/script&gt;</code></pre>\n      <p>\n        <code>show()</code> / <code>hide()</code> はありません。表示を<b>状態から導出する</b>と、\n        初期表示と更新が同じ式になるのでズレません（jQuery で「初期化だけ別に書いてズレる」のが定番事故です）。\n      </p>\n      <div class=\"note\">\n        <p style=\"margin:0\">\n          <b>見せてはいけないものは <code>when(state, { detach: true })</code> を使ってください。</b>\n          CSS で隠す方式は、class 名のタイポや CSS の1行削除で「見えてしまう側」に倒れます。\n        </p>\n      </div>\n\n      <h2 id=\"step-repeat\" class=\"anchor\">5. repeat — 一覧を描く</h2>\n      <p>雛形は <code>&lt;template&gt;</code> に置き、中身は<b>いつもの jQuery</b> で書きます。</p>\n      <pre><code>&lt;ul id=\"list\"&gt;&lt;/ul&gt;\n&lt;template id=\"row\"&gt;\n  &lt;li&gt;&lt;span class=\"title\"&gt;&lt;/span&gt; &lt;input class=\"memo\" placeholder=\"メモ\"&gt;&lt;/li&gt;\n&lt;/template&gt;\n\n&lt;script&gt;\n  const todos = $$.state([\n    { id: 1, title: \"牛乳\" },\n    { id: 2, title: \"卵\" },\n  ]);\n\n  $$(\"#list\").repeat(todos, {\n    key: (t) => t.id,\n    tpl: \"#row\",\n    render: ($row, t) => $row.find(\".title\").text(t.title),\n  });\n\n  // 1件足してみる → メモ欄に入力した文字は消えません\n  setTimeout(() => todos((list) => [...list, { id: 3, title: \"パン\" }]), 3000);\n&lt;/script&gt;</code></pre>\n      <p>\n        <b>メモ欄に何か入力してから3秒待ってください。</b>行が増えても入力した文字は残ります。\n        <code>$(\"#list\").html(…)</code> で作り直す従来の方法だと、入力もフォーカスもスクロール位置も飛びます。\n      </p>\n      <p class=\"muted\">\n        <code>&lt;table&gt;</code> の <code>&lt;tr&gt;</code> や <code>&lt;select&gt;</code> の <code>&lt;option&gt;</code> でも使えます。\n        サーバーが出力済みの一覧を乗っ取るなら <code>{ from: \"li\" }</code>。\n      </p>\n\n      <h2 id=\"step-form\" class=\"anchor\">6. フォームの事故を止める</h2>\n      <p><b>HTML は1文字も変えません。</b>既にある <code>required</code> や <code>type=\"email\"</code> を読みます。</p>\n      <pre><code>&lt;form id=\"signup\"&gt;\n  &lt;input name=\"mail\" type=\"email\" required&gt;\n  &lt;input name=\"tel\" required&gt;\n  &lt;div style=\"display:none\"&gt;\n    &lt;input name=\"promo\" required&gt;   &lt;!-- 画面に出ていない必須項目 --&gt;\n  &lt;/div&gt;\n  &lt;button type=\"submit\"&gt;送信&lt;/button&gt;\n&lt;/form&gt;\n&lt;p id=\"err\"&gt;&lt;/p&gt;\n\n&lt;script&gt;\n  const f = $$(\"#signup\").form({\n    tel: { pattern: /^0\\d{9,10}$/, message: \"電話番号の形式が違います\" },\n  });\n\n  $$(\"#err\").text(f.errorCount, \"件の未入力\");\n  f.submit(async (values) => {\n    console.log(\"送信\", values);        // 連打しても1回だけ\n    await new Promise((r) => setTimeout(r, 800));\n  });\n&lt;/script&gt;</code></pre>\n      <p>\n        メールと電話を埋めれば送信できます。<b>画面に出ていない <code>promo</code> は検証されません。</b><br />\n        標準の HTML5 検証だと、この <code>required</code> で送信がブロックされるのに理由を表示できず、\n        ユーザーには「押しても何も起きない」としか見えません。そのまま離脱します。\n      </p>\n      <p>試してみてください。</p>\n      <ul>\n        <li><b>オートフィル</b>: コンソールで <code>document.querySelector('[name=mail]').value = \"a@b.com\"</code>\n          — イベントを飛ばしていないのにエラーが消えます</li>\n        <li><b>日本語入力</b>: 電話欄で漢字変換してみてください。変換中に赤くなりません</li>\n        <li><b>連打</b>: 送信ボタンを連打しても、送信は1回だけです</li>\n      </ul>\n\n      <h2 id=\"step-component\" class=\"anchor\">7. common.js を安全にする</h2>\n      <p>\n        全ページで読まれるファイルに「手続き」を書くと、要素が無いページでも走り、\n        1箇所の undefined で以降が全部死にます。<b>「登録」だけを書く形</b>にします。\n      </p>\n      <pre><code>&lt;!-- このページで動かしたい部品を HTML 側で宣言する --&gt;\n&lt;div data-component=\"counter\" data-start=\"5\"&gt;\n  &lt;button class=\"dec\"&gt;−&lt;/button&gt;&lt;b class=\"n\"&gt;&lt;/b&gt;&lt;button class=\"inc\"&gt;＋&lt;/button&gt;\n&lt;/div&gt;\n\n&lt;script&gt;\n  // common.js に書くのはこれだけ（実行はしない）\n  $$.component(\"counter\", ($el, props, ctx) => {\n    const n = $$.state(props.start ?? 0);\n    $el.find(\".n\").text(n);\n    $el.find(\".inc\").click(() => n((v) => v + 1));\n    $el.find(\".dec\").click(() => n((v) => v - 1));\n  });\n\n  // わざと壊れる部品も置いてみる\n  $$.component(\"broken\", () => { undefined.foo; });\n&lt;/script&gt;\n&lt;div data-component=\"broken\"&gt;&lt;/div&gt;</code></pre>\n      <p>\n        <code>broken</code> は失敗しますが、<b>counter は動き続けます</b>。\n        コンソールには「失敗した部品名」と「生きている部品名」が出ます。<br />\n        <code>data-component</code> が無いページでは1行も実行されません。\n        Ajax で後から追加した要素にも自動で適用され、消えたら自動で片付きます。\n      </p>\n\n      <h2 id=\"step-migrate\" class=\"anchor\">8. 既存 jQuery と混ぜる</h2>\n      <p><b>jQuery を消す必要はありません。</b>同じページ・同じ要素で共存できます（<code>$</code> は奪いません）。</p>\n      <pre><code>&lt;script src=\"https://code.jquery.com/jquery-3.7.1.min.js\"&gt;&lt;/script&gt;\n&lt;script src=\"https://cdn.jsdelivr.net/npm/bridgey@2\"&gt;&lt;/script&gt;\n&lt;script&gt;\n  // 入力周りは既存の jQuery のまま\n  $(\"#qty\").on(\"change\", function () { /* 既存の処理 */ });\n\n  // 金額の計算だけ bridgey に移す\n  const qty   = $$(\"#qty\").state(1);\n  const total = $$.computed(() => qty() * 1100);\n  $$(\"#total\").text(total, $$.money, \"円\");\n&lt;/script&gt;</code></pre>\n      <p>\n        しかも<b>既存 jQuery が <code>$(\"#qty\").val(\"3\")</code> で値を入れても bridgey が追従します</b>\n        （<code>value</code> の代入自体を見ているため）。だから「フォームの検証だけ移す」ができます。\n      </p>\n      <p class=\"muted\">\n        ※ jQuery プラグイン（slick / DataTables 等）は bridgey では動きません。jQuery 本体と併用してください。\n      </p>\n\n      <h2 id=\"step-warn\" class=\"anchor\">9. 警告を読む</h2>\n      <p>bridgey の主な仕事は「黙って壊れないこと」です。わざと間違えてみてください。</p>\n      <pre><code>$$(\".typo-selector\").text($$.state(1));\n// → 0件でした。text() を結びつけられません。HTML が変わった可能性があります…\n\n$$(\"#box\").toggleClass(\"actve\", open);\n// → このクラスはどの CSS にも定義されていません。似ている名前: \"active\"\n\n$$(\"#list\").repeat(items, { key: () => 1, tpl: \"#row\", render: … });\n// → キーが重複しています: 1\n\n$$(\"#row\").next();\n// → next() は使えません。構造が変わると壊れるため…\n//    → closest(\"@row\").find(\"@price\") のように名前で引いてください\n\n$$(\"#box\").addClass(\"active\");\n// → 状態を表しているようです。.selected(state) が使えます（aria-selected も付きます）</code></pre>\n      <p class=\"muted\">\n        本番でうるさければ <code>$$.warn = false</code>（事故の警告）/ <code>$$.hints = false</code>（改善の提案）。\n      </p>\n\n      <h2 id=\"next\" class=\"anchor\">次に読むもの</h2>\n      <p>\n        <a class=\"btn primary\" href=\"#/examples\"><i class=\"fa-regular fa-circle-play\"></i> 複雑なフォームで jQuery と比べる</a>\n        <a class=\"btn ghost\" href=\"#/docs\"><i class=\"fa-solid fa-book\"></i> ドキュメント（全機能）</a>\n      </p>\n    </main>\n  </div>\n</div>\n","examples":"<a id=\"top\"></a>\n\n<style>\n  .ex-form { display: grid; gap: 14px; }\n  .ex-row { display: grid; gap: 4px; }\n  .ex-row label { font-size: 12.5px; color: var(--muted); }\n  .ex-row input[type=text], .ex-row input[type=email], .ex-row input[type=tel],\n  .ex-row input[type=password], .ex-row select {\n    width: 100%; padding: 9px 11px; border: 1px solid var(--line); border-radius: 8px;\n    background: transparent; color: inherit; font: inherit;\n  }\n  .ex-row input[data-invalid] { border-color: #d1242f; }\n  .ex-inline { display: flex; flex-wrap: wrap; gap: 14px; align-items: center; }\n  .ex-inline label { display: inline-flex; gap: 6px; align-items: center; color: inherit; font-size: 14px; }\n  .ex-opts { list-style: none; padding: 0; margin: 0; display: grid; gap: 6px; }\n  .ex-opts li { display: flex; align-items: center; gap: 8px; padding: 7px 9px; border-radius: 8px; }\n  .ex-opts li[data-selected] { background: color-mix(in srgb, var(--accent) 12%, transparent); }\n  .ex-total { display: flex; justify-content: space-between; align-items: baseline;\n    padding-top: 12px; border-top: 1px dashed var(--line); }\n  .ex-price { font-size: 24px; font-weight: 700; letter-spacing: -.02em; }\n  .ex-price small { font-size: 12px; font-weight: 400; opacity: .7; }\n  [data-brg-error], .bridgey-error { color: #d1242f; font-size: 12.5px; margin: 2px 0 0; }\n  .ex-log { font-size: 12.5px; color: var(--muted); background: var(--code-bg);\n    border-radius: 8px; padding: 10px 12px; white-space: pre-wrap; margin: 12px 0 0; }\n  .ex-hidden-note { font-size: 12px; color: var(--muted); }\n  .diff { width: 100%; border-collapse: collapse; font-size: 13.5px; }\n  .diff th, .diff td { text-align: left; padding: 9px 11px; border-bottom: 1px solid var(--line); vertical-align: top; }\n  .diff th { font-size: 12.5px; opacity: .7; }\n  .diff td:first-child { white-space: nowrap; }\n  .code-tabs { display: flex; gap: 6px; margin-bottom: 12px; flex-wrap: wrap; }\n  .code-tabs button { font-size: 13px; padding: 7px 14px; border-radius: 8px; cursor: pointer;\n    border: 1px solid var(--line); background: transparent; color: var(--muted); }\n  .code-tabs button[data-selected] { border-color: var(--accent); color: var(--fg);\n    background: color-mix(in srgb, var(--accent) 10%, transparent); font-weight: 600; }\n  .vs h3 { margin: 26px 0 10px; font-size: 15px; }\n  .vs pre { margin: 0; font-size: 12px; line-height: 1.65; }\n  .vs .card { display: grid; gap: 8px; align-content: start; }\n  .vs .label { font-size: 12px; }\n  .bad { color: #d1242f; } .good { color: #1a7f37; }\n  [data-theme=\"dark\"] .good { color: #3fb950; } [data-theme=\"dark\"] .bad { color: #ff7b72; }\n</style>\n\n<div class=\"wrap\">\n  <div class=\"layout\">\n    <aside class=\"toc\">\n      <div class=\"grp\">まず最小</div>\n      <a href=\"#counter\">カウンター</a>\n\n      <div class=\"grp\">やや複雑なフォーム</div>\n      <a href=\"#live\">動かしてみる</a>\n      <a href=\"#compare\">コードを並べて比べる</a>\n      <a href=\"#diff\">何が違うのか</a>\n\n      <div class=\"grp\">カート</div>\n      <a href=\"#cart\">金額を全部導出する</a>\n      <a href=\"#cart-code\">カートのコード</a>\n\n      <div class=\"grp\">一覧</div>\n      <a href=\"#todo\">ToDo（追加・絞り込み）</a>\n      <a href=\"#todo-code\">ToDo のコード</a>\n\n      <div class=\"grp\">壊れにくさ</div>\n      <a href=\"#robust\">この節について</a>\n      <a href=\"#break\">1段ラップすると壊れる</a>\n      <a href=\"#isolate\">全機能は死なない</a>\n      <a href=\"#typo\">class 名のタイポ</a>\n\n      <div class=\"grp\">その他</div>\n      <a href=\"#more\">次に読む</a>\n    </aside>\n\n    <main class=\"content\">\n      <h1>Example</h1>\n      <p class=\"muted\">\n        条件付き必須・確認入力・オプションの合計・自動整形——<b>よくある「面倒なフォーム」</b>を1つ作ってあります。<br />\n        <b>下のフォームは本当に動いています。</b>触ってから、コードを比べてください。\n      </p>\n\n      <!-- ================= COUNTER ================= -->\n      <h2 id=\"counter\" class=\"anchor\">カウンター（最小の状態管理）</h2>\n      <p>状態を1つ持って、そこから表示を導出する。<b>これが全部の基本</b>です。</p>\n\n      <!-- sample:counter:start -->\n<div class=\"card\" data-component=\"ex-counter\">\n          <div class=\"ex-total\" style=\"border:0;padding-top:0\">\n            <span>数量</span>\n            <span class=\"demo-qty\" style=\"display:inline-flex;align-items:center;gap:14px\">\n              <button type=\"button\" data-brg=\"cnt-dec\">−</button>\n              <b data-brg=\"cnt-n\" style=\"min-width:2em;text-align:center;font-size:20px\"></b>\n              <button type=\"button\" data-brg=\"cnt-inc\">＋</button>\n            </span>\n          </div>\n          <div class=\"ex-total\"><span>2倍した値</span><span data-brg=\"cnt-doubled\"></span></div>\n          <div class=\"ex-total\"><span>合計（単価 1,100円）</span>\n            <strong class=\"ex-price\"><span data-brg=\"cnt-total\"></span><small>円</small></strong></div>\n          <p class=\"good\" data-brg=\"cnt-over\">10個以上のまとめ買いです</p>\n          <p class=\"ex-hidden-note\" data-brg=\"cnt-limit\">上限は20個です</p>\n          <div class=\"ex-inline\">\n            <button type=\"button\" class=\"btn ghost\" data-brg=\"cnt-reset\" style=\"font-size:13px\">リセット</button>\n          </div>\n        </div>\n<!-- sample:counter:end -->\n\n      <div class=\"card\" style=\"margin-top:14px\">\n          <div class=\"label\"><i class=\"fa-solid fa-code\"></i> いま動いているコード</div>\n          <div data-brg=\"counter-source\"></div>\n          <template data-brg=\"counter-source-jquery\"><pre><code>// ※ 同じ画面を jQuery で書いた場合。掴む先には id / class を振った前提です。\nvar MAX_QUANTITY = 20;\nvar UNIT_PRICE   = 1100;\nvar quantity     = 1;\n\n// 表示を更新する関数を1つ作り、変えた場所すべてから呼ぶ\nfunction render() {\n  $(\"#n\").text(quantity);\n  $(\"#doubled\").text(quantity * 2);                          // 書き忘れるとここだけ古い\n  $(\"#total\").text((quantity * UNIT_PRICE).toLocaleString()); // 書き忘れると数値計算が合わない\n\n  $(\"#inc\").prop(\"disabled\", quantity >= MAX_QUANTITY);\n  $(\"#dec\").prop(\"disabled\", quantity &lt;= 1);\n  $(\"#over\").toggle(quantity >= 10);\n  $(\"#limit\").toggle(quantity >= MAX_QUANTITY);\n}\n\n$(\"#inc\").on(\"click\", function () {\n  quantity = Math.min(MAX_QUANTITY, quantity + 1);\n  render();          // ← 呼び忘れたら画面が止まる\n});\n\n$(\"#dec\").on(\"click\", function () {\n  quantity = Math.max(1, quantity - 1);\n  render();          // ← 呼び忘れたら画面が止まる\n});\n\n$(\"#reset\").on(\"click\", function () {\n  quantity = 1;\n  render();          // ← 呼び忘れたら画面が止まる\n});\n\nrender();            // 初期表示のためにもう1回\n\n// 表示を1つ足すたびに render() に行を足す。\n// 足し忘れたところだけが、黙って古い値のまま残る。</code></pre></template>\n          <p style=\"color:var(--muted);font-size:13px;margin:0\">\n            <code>doubled</code> <code>total</code> <code>over</code> <code>limit</code> ——\n            <b>どれも代入していません。</b><code>quantity</code> ひとつから導出しているだけです。\n          </p>\n      </div>\n\n      <!-- ================= LIVE ================= -->\n      <h2 id=\"live\" class=\"anchor\">やや複雑なフォーム</h2>\n\n      <!-- sample:form:start -->\n<div class=\"card\" data-component=\"ex-form\">\n        <form class=\"ex-form\" data-brg=\"form\">\n          <div class=\"ex-row\">\n            <label>お申し込み種別</label>\n            <div class=\"ex-inline\">\n              <label><input type=\"radio\" name=\"plan\" value=\"personal\" data-brg=\"plan\" checked> 個人</label>\n              <label><input type=\"radio\" name=\"plan\" value=\"corp\" data-brg=\"plan\"> 法人</label>\n            </div>\n          </div>\n\n          <div class=\"ex-row\" data-brg=\"corp-box\">\n            <label for=\"ex-company\">会社名（法人のときだけ必須）</label>\n            <input id=\"ex-company\" name=\"company\" type=\"text\" autocomplete=\"organization\">\n          </div>\n\n          <div class=\"ex-row\">\n            <label for=\"ex-mail\">メールアドレス（必須）</label>\n            <input id=\"ex-mail\" name=\"mail\" type=\"email\" required autocomplete=\"email\">\n          </div>\n\n          <div class=\"ex-row\">\n            <label for=\"ex-tel\">電話番号（必須・ハイフンなし）</label>\n            <input id=\"ex-tel\" name=\"tel\" type=\"tel\" required autocomplete=\"tel\">\n          </div>\n\n          <div class=\"ex-row\">\n            <label for=\"ex-zip\">郵便番号（入力すると自動でハイフンが入ります）</label>\n            <input id=\"ex-zip\" name=\"zip\" type=\"text\" autocomplete=\"postal-code\" placeholder=\"1000001\">\n          </div>\n\n          <div class=\"ex-row\">\n            <label for=\"ex-pass\">パスワード（8文字以上）</label>\n            <input id=\"ex-pass\" name=\"password\" type=\"password\" minlength=\"8\">\n          </div>\n          <div class=\"ex-row\">\n            <label for=\"ex-pass2\">パスワード（確認）</label>\n            <input id=\"ex-pass2\" name=\"confirm\" type=\"password\">\n          </div>\n\n          <div class=\"ex-row\">\n            <label>オプション</label>\n            <ul class=\"ex-opts\" data-brg=\"opts\"></ul>\n            <template data-brg=\"opt-tpl\">\n              <li data-brg=\"opt-row\">\n                <input type=\"checkbox\" data-brg=\"opt-check\">\n                <span data-brg=\"opt-name\" style=\"flex:1\"></span>\n                <span data-brg=\"opt-price\" class=\"ex-hidden-note\"></span>\n              </li>\n            </template>\n          </div>\n\n          <!-- 画面に出ていない必須項目。旧来のやり方だとここで CV が死ぬ -->\n          <div data-brg=\"hidden-box\" style=\"display:none\">\n            <label for=\"ex-promo\">キャンペーンコード（画面に出ていない必須項目）</label>\n            <input id=\"ex-promo\" name=\"promo\" type=\"text\" required>\n          </div>\n\n          <div class=\"ex-inline\">\n            <label><input type=\"checkbox\" name=\"agree\" data-brg=\"agree\" required> 規約に同意する（必須）</label>\n          </div>\n\n          <div class=\"ex-total\">\n            <span>オプション合計</span>\n            <strong class=\"ex-price\"><span data-brg=\"opt-total\">0</span><small>円/月</small></strong>\n          </div>\n\n          <div class=\"ex-total\" style=\"border:0\">\n            <span class=\"bad\" data-brg=\"err-summary\"></span>\n            <button type=\"submit\" class=\"btn primary\" data-brg=\"submit\">この内容で申し込む</button>\n          </div>\n          <p class=\"good\" data-brg=\"done\">送信しました</p>\n        </form>\n      </div>\n<!-- sample:form:end -->\n\n      <!-- ================= CODE（横並び） ================= -->\n      <h2 id=\"compare\" class=\"anchor\">コードを並べて比べる</h2>\n      <p class=\"muted\">\n        タブで切り替えてください。<b>bridgey 側は、いま上で動いているコードそのもの</b>です（手書きの写しではありません）。\n      </p>\n\n      <div class=\"card\">\n        <div data-brg=\"ex-source\"></div>\n        <template data-brg=\"ex-source-jquery\"><pre><code>// ※ 同じ画面を jQuery で書いた場合。掴む先には id / class を振った前提です。\n$(function () {\n  // 種別で会社名の表示と必須を切り替える\n  $('input[name=\"plan\"]').on(\"change\", function () {\n    if ($(this).val() === \"corp\") {\n      $(\"#ex-company\").closest(\".ex-row\").show();\n      $(\"#ex-company\").attr(\"required\", true);\n    } else {\n      $(\"#ex-company\").closest(\".ex-row\").hide();\n      $(\"#ex-company\").removeAttr(\"required\");\n      // ↑ 消し忘れると永久に送信できない\n    }\n    validate();   // 呼び忘れると表示がズレる\n  });\n\n  // 郵便番号の自動整形\n  $(\"#ex-zip\").on(\"input\", function () {\n    var v = $(this).val().replace(/[^0-9]/g, \"\");\n    if (v.length > 3) v = v.slice(0,3) + \"-\" + v.slice(3,7);\n    $(this).val(v);\n    // ↑ 日本語変換中にこれをやると変換が壊れる\n  });\n\n  // オプションの合計\n  function calcTotal() {\n    var total = 0;\n    $(\".ex-opts input:checked\").each(function () {\n      total += parseInt($(this).data(\"price\"), 10);\n    });\n    $(\"#opt-total\").text(total.toLocaleString());\n  }\n  $(\".ex-opts input\").on(\"change\", calcTotal);\n  // ↑ 動的に足した項目には効かない\n  calcTotal();\n  // ↑ 初期表示のために別途呼ぶ（忘れると 0 のまま）\n\n  // 検証\n  function validate() {\n    var errors = 0;\n    $(\"#ex-mail, #ex-tel, #ex-company, #ex-promo\").each(function () {\n      var $f = $(this);\n      if (!$f.attr(\"required\")) return;\n      if (!$f.is(\":visible\")) return;\n      // ↑ :visible を忘れると隠れた必須項目で\n      //   送信できず理由も出ない（CVが死ぬ）\n      var ok = $.trim($f.val()) !== \"\";\n      $f.toggleClass(\"error\", !ok);\n      // ↑ クラス名のタイポは誰も気づかない\n      if (!ok) errors++;\n    });\n    if ($(\"#ex-pass\").val() !== $(\"#ex-pass2\").val()) errors++;\n    if (!$('input[name=\"agree\"]').prop(\"checked\")) errors++;\n    $(\"#err-summary\").text(errors ? errors + \"件の未入力\" : \"\");\n    return errors === 0;\n  }\n  $(\"#ex-form input\").on(\"blur change\", validate);\n  // ↑ blur なのでオートフィルでは走らない\n\n  // 送信\n  var sending = false;\n  $(\"#ex-form\").on(\"submit\", function (e) {\n    e.preventDefault();\n    if (!validate()) return;\n    if (sending) return;   // 手で書かないと二重送信する\n    sending = true;\n    $(\"#submit\").prop(\"disabled\", true);\n    $.post(\"/api/signup\", $(this).serialize())\n      .done(function () { $(\"#done\").show(); })\n      .always(function () {\n        sending = false;\n        $(\"#submit\").prop(\"disabled\", false);\n        // ↑ 戻し忘れると永久に押せない\n      });\n  });\n});</code></pre></template>\n      </div>\n\n      <!-- ================= DIFF ================= -->\n      <h2 id=\"diff\" class=\"anchor\">何が違うのか（コードで見る）</h2>\n      <p class=\"muted\">同じ要件を、それぞれどう書くか。<b>タブで切り替えて見比べてください。</b></p>\n\n      <div class=\"vs\">\n        <h3>① 合計金額</h3>\n        <div class=\"card\" data-component=\"code-tabs\">\n          <div class=\"code-tabs\">\n            <button type=\"button\" data-brg=\"code-tab\" data-tab=\"bridgey\">bridgey</button>\n            <button type=\"button\" data-brg=\"code-tab\" data-tab=\"jquery\">jQuery</button>\n          </div>\n\n          <div data-brg=\"code-pane\" data-tab=\"bridgey\">\n            <div class=\"label good\">bridgey — 代入する場所が無い</div>\n<pre><code>const picked = $$(\".opts input\").group();\nconst total  = $$.computed(() =&gt;\n  picked().reduce((s, id) =&gt; s + PRICE[id], 0)\n);\n\n$$(\"#total\").text(total, $$.money);\n\n// 初期表示も更新も同じ式\n// 動的に足した項目も自動で入る</code></pre>\n          </div>\n\n          <div data-brg=\"code-pane\" data-tab=\"jquery\">\n            <div class=\"label bad\">jQuery — 3箇所から呼ぶ</div>\n<pre><code>function calcTotal() {\n  var total = 0;\n  $(\".opts input:checked\").each(function () {\n    total += parseInt($(this).data(\"price\"), 10);\n  });\n  $(\"#total\").text(total.toLocaleString());\n}\n$(\".opts input\").on(\"change\", calcTotal);\ncalcTotal();   // 初期表示のために別途呼ぶ\n\n// 動的に足した項目には効かない\n// 呼び忘れた画面だけ数値がズレる</code></pre>\n          </div>\n        </div>\n\n        <h3>② 画面に出ていない必須項目</h3>\n        <div class=\"card\" data-component=\"code-tabs\">\n          <div class=\"code-tabs\">\n            <button type=\"button\" data-brg=\"code-tab\" data-tab=\"bridgey\">bridgey</button>\n            <button type=\"button\" data-brg=\"code-tab\" data-tab=\"jquery\">jQuery</button>\n          </div>\n\n          <div data-brg=\"code-pane\" data-tab=\"bridgey\">\n            <div class=\"label good\">bridgey — 書くことが無い</div>\n<pre><code>const f = $$(\"#form\").form();\n\n// 見えているフィールドだけを毎回判定する。\n// これが既定の動作なので、書き忘れようがない。</code></pre>\n          </div>\n\n          <div data-brg=\"code-pane\" data-tab=\"jquery\">\n            <div class=\"label bad\">jQuery — 自分で :visible を見る</div>\n<pre><code>$(\"#form input[required]\").each(function () {\n  var $f = $(this);\n  if (!$f.is(\":visible\")) return;\n  // ↑ この1行を忘れると、画面に出ていない\n  //   required で送信がブロックされ、\n  //   エラーも表示できない（理由が出ない）\n  if ($.trim($f.val()) === \"\") errors++;\n});</code></pre>\n          </div>\n        </div>\n\n        <h3>③ 条件付き必須（法人のときだけ会社名）</h3>\n        <div class=\"card\" data-component=\"code-tabs\">\n          <div class=\"code-tabs\">\n            <button type=\"button\" data-brg=\"code-tab\" data-tab=\"bridgey\">bridgey</button>\n            <button type=\"button\" data-brg=\"code-tab\" data-tab=\"jquery\">jQuery</button>\n          </div>\n\n          <div data-brg=\"code-pane\" data-tab=\"bridgey\">\n            <div class=\"label good\">bridgey — 条件を1行書く</div>\n<pre><code>const plan = $$('input[name=\"plan\"]').group();\n\n$$(\"#company-box\").when(() =&gt; plan() === \"corp\");\n\nconst f = $$(\"#form\").form({\n  company: { required: () =&gt; plan() === \"corp\" },\n});\n\n// 表示条件と必須条件が同じ state から出るので\n// 片方だけ直し忘れることが起きない</code></pre>\n          </div>\n\n          <div data-brg=\"code-pane\" data-tab=\"jquery\">\n            <div class=\"label bad\">jQuery — 属性を付け外しする</div>\n<pre><code>$('input[name=\"plan\"]').on(\"change\", function () {\n  if ($(this).val() === \"corp\") {\n    $(\"#company\").closest(\".row\").show();\n    $(\"#company\").attr(\"required\", true);\n  } else {\n    $(\"#company\").closest(\".row\").hide();\n    $(\"#company\").removeAttr(\"required\");\n    // ↑ 消し忘れると永久に送信できない\n  }\n  validate();   // 呼び忘れると表示がズレる\n});</code></pre>\n          </div>\n        </div>\n\n        <h3>④ オートフィル・JS 代入で値が入ったとき</h3>\n        <div class=\"card\" data-component=\"code-tabs\">\n          <div class=\"code-tabs\">\n            <button type=\"button\" data-brg=\"code-tab\" data-tab=\"bridgey\">bridgey</button>\n            <button type=\"button\" data-brg=\"code-tab\" data-tab=\"jquery\">jQuery</button>\n          </div>\n\n          <div data-brg=\"code-pane\" data-tab=\"bridgey\">\n            <div class=\"label good\">bridgey — 値の代入自体を見る</div>\n<pre><code>const f = $$(\"#form\").form();\n\n// input / change に加えて\n//   ・value プロパティへの代入\n//   ・:-webkit-autofill の検知\n//   ・送信時の再読み込み\n// の4段で拾うので取りこぼさない</code></pre>\n          </div>\n\n          <div data-brg=\"code-pane\" data-tab=\"jquery\">\n            <div class=\"label bad\">jQuery — イベント待ちなので走らない</div>\n<pre><code>$(\"#form input\").on(\"blur change\", validate);\n\n// ブラウザの自動入力は input を飛ばさない。\n// $(\"#mail\").val(\"a@b.com\") でも飛ばない。\n// → 埋まっているのに「未入力」のまま\n//    ボタンが押せず、理由も分からない</code></pre>\n          </div>\n        </div>\n\n        <h3>⑤ 二重送信</h3>\n        <div class=\"card\" data-component=\"code-tabs\">\n          <div class=\"code-tabs\">\n            <button type=\"button\" data-brg=\"code-tab\" data-tab=\"bridgey\">bridgey</button>\n            <button type=\"button\" data-brg=\"code-tab\" data-tab=\"jquery\">jQuery</button>\n          </div>\n\n          <div data-brg=\"code-pane\" data-tab=\"bridgey\">\n            <div class=\"label good\">bridgey — 送信処理だけ書く</div>\n<pre><code>const f = $$(\"#form\").form();\n\n$$(\"#submit\").disabled(f.submitting);\n\nf.submit(async (values) =&gt; {\n  await fetch(\"/api\", {\n    method: \"POST\", body: JSON.stringify(values),\n  });\n});\n\n// 実行中の再送信は無視される\n// 失敗しても submitting は必ず戻る</code></pre>\n          </div>\n\n          <div data-brg=\"code-pane\" data-tab=\"jquery\">\n            <div class=\"label bad\">jQuery — フラグを手で管理する</div>\n<pre><code>var sending = false;\n$(\"#form\").on(\"submit\", function (e) {\n  e.preventDefault();\n  if (sending) return;\n  sending = true;\n  $(\"#submit\").prop(\"disabled\", true);\n  $.post(\"/api\", $(this).serialize())\n    .always(function () {\n      sending = false;\n      $(\"#submit\").prop(\"disabled\", false);\n      // ↑ 戻し忘れると永久に押せない\n    });\n});</code></pre>\n          </div>\n        </div>\n\n        <h3>⑥ 日本語入力（郵便番号の自動整形）</h3>\n        <div class=\"card\" data-component=\"code-tabs\">\n          <div class=\"code-tabs\">\n            <button type=\"button\" data-brg=\"code-tab\" data-tab=\"bridgey\">bridgey</button>\n            <button type=\"button\" data-brg=\"code-tab\" data-tab=\"jquery\">jQuery</button>\n          </div>\n\n          <div data-brg=\"code-pane\" data-tab=\"bridgey\">\n            <div class=\"label good\">bridgey — 同じ整形を書いても壊れない</div>\n<pre><code>const zip = $$(\"#zip\").state(\"\");\n\n$$(\"#zip\").val(() =&gt; {\n  const d = zip().replace(/[^0-9]/g, \"\").slice(0, 7);\n  return d.length &gt; 3 ? d.slice(0,3) + \"-\" + d.slice(3) : d;\n});\n\n// 変換中は state も DOM も触らない。\n// 確定した瞬間に一度だけ同期する</code></pre>\n          </div>\n\n          <div data-brg=\"code-pane\" data-tab=\"jquery\">\n            <div class=\"label bad\">jQuery — 変換中に書き戻して壊れる</div>\n<pre><code>$(\"#zip\").on(\"input\", function () {\n  var v = $(this).val().replace(/[^0-9]/g, \"\");\n  if (v.length &gt; 3) v = v.slice(0,3) + \"-\" + v.slice(3,7);\n  $(this).val(v);\n  // ↑ 漢字変換の最中にも input は飛ぶ。\n  //   ここで書き戻すと変換候補が消え、\n  //   確定できず、文字が化ける\n});</code></pre>\n          </div>\n        </div>\n\n        <h3>⑦ エラー表示</h3>\n        <div class=\"card\" data-component=\"code-tabs\">\n          <div class=\"code-tabs\">\n            <button type=\"button\" data-brg=\"code-tab\" data-tab=\"bridgey\">bridgey</button>\n            <button type=\"button\" data-brg=\"code-tab\" data-tab=\"jquery\">jQuery</button>\n          </div>\n\n          <div data-brg=\"code-pane\" data-tab=\"bridgey\">\n            <div class=\"label good\">bridgey — 自動で付く</div>\n<pre><code>const f = $$(\"#form\").form();\n\n// aria-invalid と data-invalid が自動で付き、\n// エラー文の置き場所も自動で用意される。\n// CSS に無いクラス名を使ったら警告が出る</code></pre>\n          </div>\n\n          <div data-brg=\"code-pane\" data-tab=\"jquery\">\n            <div class=\"label bad\">jQuery — クラス名の文字列</div>\n<pre><code>$f.toggleClass(\"error\", !ok);\n$(\"#mail-err\").text(ok ? \"\" : \"入力してください\");\n\n// \"error\" が \"eror\" でも例外は出ない。\n// CSS に届かないので赤くならず、誰も気づかない</code></pre>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"card\" style=\"margin-top:22px\">\n        <table class=\"diff\">\n          <thead><tr><th></th><th>jQuery</th><th>bridgey</th></tr></thead>\n          <tbody>\n            <tr><td>行数</td><td class=\"bad\">約 70 行</td><td class=\"good\">約 25 行</td></tr>\n            <tr><td>「呼び忘れ」で壊れる箇所</td><td class=\"bad\">4箇所（初期表示・変更・削除・追加）</td><td class=\"good\">0（導出しているだけ）</td></tr>\n            <tr><td>自分で書かないと事故る対策</td><td class=\"bad\">:visible / 二重送信フラグ / 再バインド / 日本語入力</td><td class=\"good\">全部、既定の動作</td></tr>\n          </tbody>\n        </table>\n      </div>\n\n      <div class=\"note\" style=\"margin-top:16px\">\n        <p style=\"margin:0\">\n          <b>jQuery を消す必要はありません。</b>入力周りは既存のまま残して、\n          <b>検証と合計だけ</b>を bridgey に移せます（<code>$(el).val(…)</code> で入れた値も追従します）。\n          1機能ずつ小さく始められます。\n        </p>\n      </div>\n\n      <!-- ================= CART ================= -->\n      <h2 id=\"cart\" class=\"anchor\">カート — 金額を全部導出する</h2>\n      <p>\n        小計・送料・クーポン・消費税・合計。<b>金額に代入している行が1つもありません。</b><br />\n        数量を変えても、行を消しても、クーポンを外しても、合計が合わなくなる余地がありません。\n      </p>\n\n      <!-- sample:cart:start -->\n<div class=\"card\" data-component=\"ex-cart\">\n        <ul class=\"ex-opts\" data-brg=\"rows\" style=\"gap:2px\"></ul>\n        <template data-brg=\"row-tpl\">\n          <li data-brg=\"row\" style=\"gap:12px\">\n            <span data-brg=\"name\" style=\"flex:1\"></span>\n            <span class=\"ex-hidden-note\" data-brg=\"unit\"></span>\n            <span style=\"display:inline-flex;align-items:center;gap:8px\">\n              <button type=\"button\" data-brg=\"dec\" aria-label=\"減らす\">−</button>\n              <b data-brg=\"qty\" style=\"min-width:1.6em;text-align:center\"></b>\n              <button type=\"button\" data-brg=\"inc\" aria-label=\"増やす\">＋</button>\n            </span>\n            <span data-brg=\"line\" style=\"min-width:5.5em;text-align:right\"></span>\n            <button type=\"button\" data-brg=\"del\" aria-label=\"削除\">×</button>\n          </li>\n        </template>\n\n        <p data-brg=\"empty\" style=\"text-align:center;color:var(--muted);padding:18px 0\">\n          カートは空です\n        </p>\n\n        <div data-brg=\"summary\">\n          <div class=\"ex-total\"><span>小計</span><span data-brg=\"subtotal\"></span></div>\n          <div class=\"ex-total\"><span data-brg=\"ship-label\">送料</span><span data-brg=\"ship\"></span></div>\n          <div class=\"ex-total\"><span>クーポン</span><span data-brg=\"discount\"></span></div>\n          <div class=\"ex-total\"><span>消費税（10%）</span><span data-brg=\"tax\"></span></div>\n          <div class=\"ex-total\" style=\"border-top:2px solid var(--line)\">\n            <b>合計</b>\n            <strong class=\"ex-price\"><span data-brg=\"total\"></span><small>円</small></strong>\n          </div>\n        </div>\n\n        <div class=\"ex-inline\" style=\"margin-top:14px\">\n          <label><input type=\"checkbox\" data-brg=\"coupon\"> クーポンを使う（10% OFF）</label>\n          <button type=\"button\" class=\"btn ghost\" data-brg=\"restore\" style=\"font-size:13px\">商品を戻す</button>\n        </div>\n        <p class=\"ex-hidden-note\" data-brg=\"free-note\">\n<!-- sample:cart:end -->\n          あと <b data-brg=\"to-free\"></b> 円で送料無料になります\n        </p>\n      </div>\n\n      <h2 id=\"cart-code\" class=\"anchor\">カートのコード</h2>\n      <p class=\"muted\">\n        <b>bridgey 側は、いま上で動いているコードそのもの</b>です。タブで切り替えてください。\n      </p>\n\n      <div class=\"card\">\n        <div data-brg=\"cart-source\"></div>\n        <template data-brg=\"cart-source-jquery\"><pre><code>// ※ 同じ画面を jQuery で書いた場合。掴む先には id / class を振った前提です。\n// 金額を計算して「書き込む」関数を1つ作る。ここが事故の入口。\nfunction calcTotal() {\n  var subtotal = 0;\n\n  $(\"#cart .row\").each(function () {\n    var unit = Number($(this).data(\"unit\"));\n    var qty  = Number($(this).find(\".qty\").text());\n\n    subtotal += unit * qty;\n    $(this).find(\".line\").text((unit * qty).toLocaleString() + \"円\");\n  });\n\n  var ship     = subtotal === 0 ? 0 : (subtotal >= 30000 ? 0 : 550);\n  var discount = $(\"#coupon\").prop(\"checked\") ? Math.floor(subtotal * 0.1) : 0;\n  var taxable  = subtotal - discount + ship;\n  var tax      = Math.floor(taxable * 0.1);\n\n  // 表示する場所の数だけ「代入」が並ぶ。1つ書き忘れるとそこだけ古い値が残る\n  $(\"#subtotal\").text(subtotal.toLocaleString() + \"円\");\n  $(\"#ship\").text(ship === 0 ? \"無料\" : ship.toLocaleString() + \"円\");\n  $(\"#discount\").text(\"-\" + discount.toLocaleString() + \"円\");\n  $(\"#tax\").text(tax.toLocaleString() + \"円\");\n  $(\"#total\").text((taxable + tax).toLocaleString());\n\n  // 空になったときの表示も、ここで面倒を見るしかない\n  if ($(\"#cart .row\").length === 0) {\n    $(\"#empty\").show();\n    $(\"#summary\").hide();\n  }\n}\n\n$(\"#cart\").on(\"click\", \".inc\", function () {\n  var $qty = $(this).closest(\".row\").find(\".qty\");   // 構造に依存する\n\n  $qty.text(Number($qty.text()) + 1);\n  calcTotal();          // ← 呼び忘れたら数値計算が合わない\n});\n\n$(\"#cart\").on(\"click\", \".dec\", function () {\n  var $qty = $(this).closest(\".row\").find(\".qty\");\n\n  $qty.text(Math.max(1, Number($qty.text()) - 1));\n  calcTotal();          // ← 呼び忘れたら数値計算が合わない\n});\n\n$(\"#cart\").on(\"click\", \".del\", function () {\n  $(this).closest(\".row\").remove();\n  calcTotal();          // ← 呼び忘れたら数値計算が合わない\n});\n\n$(\"#coupon\").on(\"change\", calcTotal);   // ← 呼び忘れたら数値計算が合わない\n\ncalcTotal();            // 初期表示のためにもう1回（これも忘れがち）</code></pre></template>\n      </div>\n\n      <div class=\"note\">\n        <p style=\"margin:0\">\n          <b>右は「計算して代入する」、左は「導出する」。</b>\n          jQuery 側は <code>calcTotal()</code> を<b>数量変更・削除・クーポン・初期表示の4箇所から呼び</b>、\n          さらに表示先の数だけ <code>.text()</code> で代入しています。\n          <b>呼び忘れも書き忘れも起こりうる場所が、それだけあるということです。</b>\n          bridgey 側には金額に代入している行が1つもないので、ズレようがありません。\n        </p>\n      </div>\n\n      <!-- ================= TODO ================= -->\n      <h2 id=\"todo\" class=\"anchor\">ToDo（一覧の状態管理）</h2>\n      <p>\n        追加・完了・削除・絞り込み・残り件数。<b>一覧は <code>repeat()</code> が描くので、\n        入力途中の文字やチェック状態が消えません。</b>\n      </p>\n\n      <!-- sample:todo:start -->\n<div class=\"card\" data-component=\"ex-todo\">\n        <div class=\"ex-inline\" style=\"gap:8px\">\n          <input type=\"text\" data-brg=\"input\" placeholder=\"やることを入力して Enter\"\n                 style=\"flex:1;min-width:12em;padding:9px 11px;border:1px solid var(--line);border-radius:8px;background:transparent;color:inherit;font:inherit\">\n          <button type=\"button\" class=\"btn primary\" data-brg=\"add\" style=\"font-size:13px\">追加</button>\n        </div>\n\n        <div class=\"ex-inline\" style=\"margin-top:12px\">\n          <label><input type=\"radio\" name=\"todo-filter\" value=\"all\" data-brg=\"filter\" checked> すべて</label>\n          <label><input type=\"radio\" name=\"todo-filter\" value=\"open\" data-brg=\"filter\"> 未完了</label>\n          <label><input type=\"radio\" name=\"todo-filter\" value=\"done\" data-brg=\"filter\"> 完了</label>\n          <span class=\"ex-hidden-note\" data-brg=\"counts\"></span>\n        </div>\n\n        <ul class=\"ex-opts\" data-brg=\"list\" style=\"margin-top:10px\"></ul>\n        <template data-brg=\"todo-tpl\">\n          <li data-brg=\"item\">\n            <input type=\"checkbox\" data-brg=\"check\">\n            <span data-brg=\"title\" style=\"flex:1\"></span>\n            <input type=\"text\" data-brg=\"memo\" placeholder=\"メモ\"\n                   style=\"width:9em;padding:5px 8px;border:1px solid var(--line);border-radius:6px;background:transparent;color:inherit;font:inherit;font-size:12px\">\n            <button type=\"button\" data-brg=\"del\">×</button>\n          </li>\n        </template>\n\n        <p data-brg=\"empty\" style=\"text-align:center;color:var(--muted);padding:14px 0\">該当するものがありません</p>\n<!-- sample:todo:end -->\n        <p class=\"ex-hidden-note\">\n          メモ欄に何か入力してから、別の項目を追加・完了・削除してみてください。<b>入力した文字は消えません。</b>\n        </p>\n      </div>\n\n      <h2 id=\"todo-code\" class=\"anchor\">ToDo のコード</h2>\n      <p class=\"muted\">\n        <b>bridgey 側は、いま上で動いているコードそのもの</b>です。タブで切り替えてください。\n      </p>\n\n      <div class=\"card\">\n        <div data-brg=\"todo-source\"></div>\n        <template data-brg=\"todo-source-jquery\"><pre><code>// ※ 同じ画面を jQuery で書いた場合。掴む先には id / class を振った前提です。\nvar todos  = [\n  { id: 1, title: \"見積書を送る\", done: false },\n  { id: 2, title: \"請求書を確認する\", done: true }\n];\nvar nextId = 3;\nvar filter = \"all\";\n\n// 一覧を作り直す。1行変えるだけでも全部作り直すことになる\nfunction render() {\n  var html = \"\";\n\n  $.each(todos, function (i, todo) {\n    if (filter === \"open\" && todo.done) return;\n    if (filter === \"done\" && !todo.done) return;\n\n    html += '&lt;li class=\"item' + (todo.done ? \" done\" : \"\") + '\" data-id=\"' + todo.id + '\"&gt;'\n          +   '&lt;input type=\"checkbox\" class=\"check\"' + (todo.done ? \" checked\" : \"\") + '&gt;'\n          +   '&lt;span class=\"title\"&gt;' + todo.title + \"&lt;/span&gt;\"\n          +   '&lt;input type=\"text\" class=\"memo\" placeholder=\"メモ\"&gt;'\n          +   '&lt;button class=\"del\"&gt;削除&lt;/button&gt;'\n          + \"&lt;/li&gt;\";\n  });\n\n  $(\"#list\").html(html);   // ← ここで起きること:\n                           //    ・メモ欄に入力途中だった文字が消える\n                           //    ・フォーカスもスクロール位置も飛ぶ\n                           //    ・開いていた行が閉じる\n  updateCounts();          // ← 呼び忘れたら件数だけ古いまま\n}\n\nfunction updateCounts() {\n  var remaining = $.grep(todos, function (t) { return !t.done; }).length;\n\n  $(\"#counts\").text(remaining + \"件が未完了\");\n  $(\"#empty\").toggle($(\"#list .item\").length === 0);\n}\n\n// 作り直すので、ハンドラは毎回張り直すか委譲するしかない\n$(\"#list\").on(\"change\", \".check\", function () {\n  var id = $(this).closest(\".item\").data(\"id\");   // 構造に依存する\n\n  $.each(todos, function (i, todo) {\n    if (todo.id === id) todo.done = $(this).prop(\"checked\");\n  }.bind(this));\n\n  render();\n});\n\n$(\"#list\").on(\"click\", \".del\", function () {\n  var id = $(this).closest(\".item\").data(\"id\");\n\n  todos = $.grep(todos, function (t) { return t.id !== id; });\n  render();\n});\n\n$(\"#add\").on(\"click\", function () {\n  var title = $.trim($(\"#input\").val());\n  if (!title) return;\n\n  todos.push({ id: nextId++, title: title, done: false });\n  $(\"#input\").val(\"\");\n  render();\n});\n\n$(\".filter\").on(\"change\", function () {\n  filter = $(this).val();\n  render();\n});\n\nrender();   // 初期表示のためにもう1回</code></pre></template>\n      </div>\n\n      <div class=\"note\">\n        <p style=\"margin:0\">\n          <b><code>.html()</code> で作り直すと、入力途中の文字もフォーカスも消えます。</b>\n          bridgey の <code>repeat()</code> はキーが同じ行の DOM を使い回すので、\n          <b>上のデモでメモ欄に入力したまま追加や絞り込みをしても消えません。</b>\n          件数の更新も導出なので、<code>updateCounts()</code> の呼び忘れ自体が存在しません。\n        </p>\n      </div>\n\n      <!-- ================= 壊れにくさ ================= -->\n      <hr style=\"border:0;border-top:1px solid var(--line);margin:56px 0 0\" />\n\n      <h2 id=\"robust\" class=\"anchor\">壊れにくさ — bridgey が黙らせない事故</h2>\n      <p class=\"muted\">\n        ここから下は「同じ画面をどう書くか」ではなく、\n        <b>書き方に関係なく襲ってくる事故</b>を bridgey がどう止めるかの実演です。\n        どれも<b>その場で触って確かめられます</b>。\n      </p>\n\n      <h3 id=\"break\" class=\"anchor\">HTML を1段ラップすると、黙って壊れる</h3>\n      <p>\n        <code>next()</code> や <code>children()</code> で「隣の要素」を掴んでいるコードは、\n        <b>HTML に要素を1つ挟むだけで動かなくなります。しかも例外は出ません。</b><br />\n        デザイナーが <code>&lt;div&gt;</code> を1枚足しただけ——という壊れ方です。\n      </p>\n\n      <div data-component=\"ex-structure\">\n        <div class=\"two\">\n          <div class=\"card\">\n            <div class=\"label\"><i class=\"fa-solid fa-triangle-exclamation\"></i> 従来のやり方（隣を掴む）</div>\n            <div>\n              <button type=\"button\" class=\"btn ghost\" data-brg=\"old-head\">内訳を開く</button>\n              <div data-brg=\"old-body\" style=\"display:none;padding-top:10px\">\n                基本料金 23,800円 ／ 追加料金 2,200円\n              </div>\n            </div>\n            <p class=\"ex-log\" data-brg=\"old-log\">まだ壊れていません。</p>\n          </div>\n\n          <div class=\"card\">\n            <div class=\"label\"><i class=\"fa-solid fa-check\"></i> bridgey（名前で引く）</div>\n            <div>\n              <button type=\"button\" class=\"btn ghost\" data-brg=\"new-head\">内訳を開く</button>\n              <div data-brg=\"new-body\" style=\"padding-top:10px\">\n                基本料金 23,800円 ／ 追加料金 2,200円\n              </div>\n            </div>\n            <p class=\"ex-log\" data-brg=\"new-log\">まだ壊れていません。</p>\n          </div>\n        </div>\n\n        <p style=\"margin-top:14px\">\n          <button type=\"button\" class=\"btn\" data-brg=\"wrap\">\n            <i class=\"fa-solid fa-layer-group\"></i> 両方の HTML を &lt;div&gt; で1段ラップする\n          </button>\n        </p>\n      </div>\n\n      <h3 id=\"isolate\" class=\"anchor\">1つの undefined で、全機能は死なない</h3>\n      <p>\n        同じ <code>$(function(){})</code> の中に全部書いていると、\n        <b>最初の1行が落ちた時点で、後ろのタブもカウンターも巻き添えで死にます。</b><br />\n        bridgey は部品ごとに切り離すので、壊れた部品だけが止まります。\n      </p>\n\n      <div class=\"card\">\n        <!-- わざと初期化に失敗する部品。存在しない要素を触る -->\n        <div data-component=\"ex-broken\"></div>\n\n        <div data-component=\"ex-tabs\" style=\"margin-bottom:12px\">\n          <div class=\"code-tabs\">\n            <button type=\"button\" data-brg=\"tab\" data-tab=\"a\">料金</button>\n            <button type=\"button\" data-brg=\"tab\" data-tab=\"b\">スペック</button>\n          </div>\n          <div data-brg=\"pane\" data-tab=\"a\">料金の中身です。</div>\n          <div data-brg=\"pane\" data-tab=\"b\">スペックの中身です。</div>\n        </div>\n\n        <div class=\"ex-inline\" data-component=\"ex-mini\">\n          <button type=\"button\" class=\"btn ghost\" data-brg=\"mini-dec\">−</button>\n          <b data-brg=\"mini-n\" style=\"min-width:2em;text-align:center\"></b>\n          <button type=\"button\" class=\"btn ghost\" data-brg=\"mini-inc\">＋</button>\n        </div>\n\n        <p class=\"ex-log\">\n          この上には<b>初期化に失敗した部品が1つ混ざっています</b>（コンソールに理由が出ています）。\n          それでもタブとカウンターは動きます。\n        </p>\n      </div>\n\n      <h3 id=\"typo\" class=\"anchor\">class 名のタイポは、その場で教える</h3>\n      <p>\n        表示の出し入れを class で行っていると、<b>綴りを間違えた瞬間に「隠したはずのものが見えたまま」</b>になります。\n        CSS に無いクラスで状態を切り替えようとしたら、bridgey は似ている名前を添えて知らせます。\n      </p>\n\n      <div class=\"card\" data-component=\"ex-typo\">\n        <p style=\"margin:0 0 10px\">\n          <button type=\"button\" class=\"btn\" data-brg=\"run\">\n            <i class=\"fa-solid fa-spell-check\"></i> CSS に無いクラスで表示を切り替える\n          </button>\n        </p>\n        <p class=\"ex-log\" data-brg=\"typo-log\">押すと、bridgey が出す警告をそのまま表示します。</p>\n      </div>\n\n      <h2 id=\"more\" class=\"anchor\">次に読む</h2>\n      <p>\n        <a class=\"btn ghost\" href=\"#/tutorial\"><i class=\"fa-solid fa-graduation-cap\"></i> チュートリアル</a>\n        <a class=\"btn ghost\" href=\"#/docs\"><i class=\"fa-solid fa-book\"></i> ドキュメント</a>\n      </p>\n    </main>\n  </div>\n</div>\n"};
